    for (let i = 0; i < eucVec.length; i++) {
      expect(back[i]).toBeCloseTo(eucVec[i], 4);
    }
  });

  it('hyperbolicDistance: self = 0', () => {
    const p = euclideanToPoincare(new Float32Array([0.1, 0.1, 0.1]));
    expect(hyperbolicDistance(p, p)).toBeCloseTo(0, 5);
  });

