import { describe, it, expect } from 'vitest';

// Import only lightweight utilities
import {
  chunkText,
  estimateTokens,
  reconstructFromChunks,
} from '../src/chunking.js';

import {
  l2Normalize,
  l1Normalize,
  minMaxNormalize,
  zScoreNormalize,
  normalize,
  l2Norm,
  isNormalized,
} from '../src/normalization.js';

import {
  euclideanToPoincare,
  poincareToEuclidean,
  hyperbolicDistance,
  mobiusAdd,
  isInPoincareBall,
  batchEuclideanToPoincare,
} from '../src/hyperbolic.js';

