      expect(result.metric).toBe('euclidean');
      expect(result.score).toBeCloseTo(1 / (1 + Math.sqrt(2)));
    });

    it('should support dot product metric', () => {
      const result = computeSimilarity(vec1, vec4, 'dot');
      expect(result.metric).toBe('dot');
      expect(result.score).toBeCloseTo(-1);
    });
  });
});

/**
 * Document Chunking Utilities
 *
 * Features:
 * - Configurable chunk size and overlap
 * - Sentence-aware splitting
 * - Paragraph-aware splitting
 * - Token-based chunking (approximate)
 * - Metadata tracking for reconstruction
 */

/**
 * Chunking configuration
 */
export interface ChunkingConfig {
  /** Maximum chunk size in characters (default: 512) */
  maxChunkSize?: number;
  /** Overlap between chunks in characters (default: 50) */
  overlap?: number;
  /** Strategy for splitting (default: 'sentence') */
  strategy?: 'character' | 'sentence' | 'paragraph' | 'token';
  /** Minimum chunk size (default: 100) */
  minChunkSize?: number;
  /** Include metadata with chunks */
  includeMetadata?: boolean;
}

/**
 * Chunk result with metadata
 */
export interface Chunk {
  /** Chunk text content */
  text: string;
  /** Original index in document */
  index: number;
  /** Start position in original text */
  startPos: number;
  /** End position in original text */
  endPos: number;
  /** Character count */
  length: number;
  /** Approximate token count (chars / 4) */
  tokenCount: number;
}

/**
 * Chunked document result
 */
export interface ChunkedDocument {
  /** Array of chunks */
  chunks: Chunk[];
  /** Original text length */
  originalLength: number;
  /** Total chunks created */
  totalChunks: number;
  /** Configuration used */
  config: Required<ChunkingConfig>;
}

// Sentence boundary patterns
const SENTENCE_ENDINGS = /(?<=[.!?])\s+(?=[A-Z])/g;
const PARAGRAPH_BREAKS = /\n\n+/g;

/**
 * Split text into chunks with overlap
 */
export function chunkText(
  text: string,
  config: ChunkingConfig = {}
): ChunkedDocument {
  const maxChunkSize = config.maxChunkSize ?? 512;
  const finalConfig: Required<ChunkingConfig> = {
    maxChunkSize,
    overlap: Math.min(config.overlap ?? 50, maxChunkSize - 1),
    strategy: config.strategy ?? 'sentence',
    minChunkSize: config.minChunkSize ?? 100,
    includeMetadata: config.includeMetadata ?? true,
  };

  // Normalize whitespace
  const normalizedText = text.replace(/\s+/g, ' ').trim();

  let chunks: Chunk[];

  switch (finalConfig.strategy) {
    case 'character':
      chunks = chunkByCharacter(normalizedText, finalConfig);
      break;
    case 'sentence':
      chunks = chunkBySentence(normalizedText, finalConfig);
      break;
    case 'paragraph':
      chunks = chunkByParagraph(text, finalConfig); // Keep original for paragraphs
      break;
    case 'token':
      chunks = chunkByToken(normalizedText, finalConfig);
      break;
    default:
      chunks = chunkBySentence(normalizedText, finalConfig);
  }

  return {
    chunks,
    originalLength: text.length,
    totalChunks: chunks.length,
    config: finalConfig,
  };
}

/**
 * Simple character-based chunking with overlap
 */
function chunkByCharacter(
  text: string,
  config: Required<ChunkingConfig>
): Chunk[] {
  const chunks: Chunk[] = [];
  const { maxChunkSize, overlap } = config;

  let pos = 0;
  let index = 0;

  while (pos < text.length) {
    const endPos = Math.min(pos + maxChunkSize, text.length);
    const chunkText = text.slice(pos, endPos);

    chunks.push({
      text: chunkText,
      index,
      startPos: pos,
      endPos,
      length: chunkText.length,
      tokenCount: Math.ceil(chunkText.length / 4),
    });

    // Move position with overlap, ensuring forward progress
    const nextPos = endPos - overlap;
    pos = nextPos <= pos ? pos + 1 : nextPos;
    if (pos >= text.length) {
      break;
    }
    index++;
  }

  return chunks;
}

/**
 * Sentence-aware chunking - keeps sentences intact
 */
function chunkBySentence(
  text: string,
  config: Required<ChunkingConfig>
): Chunk[] {
  const { maxChunkSize, overlap, minChunkSize } = config;

  // Split into sentences
  const sentences = text.split(SENTENCE_ENDINGS).filter(s => s.trim().length > 0);

  const chunks: Chunk[] = [];
  let currentChunk = '';
  let currentStart = 0;
  let index = 0;
  let textPos = 0;

  for (const sentence of sentences) {
    const trimmedSentence = sentence.trim();

    // If adding this sentence exceeds max size, save current chunk
    if (currentChunk.length + trimmedSentence.length > maxChunkSize && currentChunk.length >= minChunkSize) {
      chunks.push({
        text: currentChunk.trim(),
        index,
        startPos: currentStart,
        endPos: textPos,
        length: currentChunk.length,
        tokenCount: Math.ceil(currentChunk.length / 4),
      });

      // Start new chunk with overlap (last part of previous chunk)
      const overlapText = currentChunk.slice(-overlap);
      currentChunk = overlapText + ' ' + trimmedSentence;
      currentStart = textPos - overlap;
      index++;
    } else {
      currentChunk += (currentChunk.length > 0 ? ' ' : '') + trimmedSentence;
    }

    textPos += trimmedSentence.length + 1;
  }

  // Add final chunk
  if (currentChunk.trim().length > 0) {
    chunks.push({
      text: currentChunk.trim(),
      index,
      startPos: currentStart,
      endPos: text.length,
      length: currentChunk.length,
      tokenCount: Math.ceil(currentChunk.length / 4),
    });
  }

  return chunks;
}

/**
 * Paragraph-aware chunking
 */
function chunkByParagraph(
  text: string,
  config: Required<ChunkingConfig>
): Chunk[] {
  const { maxChunkSize, minChunkSize } = config;

  // Split by paragraph breaks
  const paragraphs = text.split(PARAGRAPH_BREAKS).filter(p => p.trim().length > 0);

  const chunks: Chunk[] = [];
  let currentChunk = '';
  let currentStart = 0;
  let index = 0;
  let textPos = 0;

  for (const paragraph of paragraphs) {
    const trimmedPara = paragraph.trim();

    // If single paragraph exceeds max, fall back to sentence chunking
    if (trimmedPara.length > maxChunkSize) {
      if (currentChunk.length > 0) {
        chunks.push({
          text: currentChunk.trim(),
          index,
          startPos: currentStart,
          endPos: textPos,
          length: currentChunk.length,
          tokenCount: Math.ceil(currentChunk.length / 4),
        });
        index++;
      }

      // Chunk the large paragraph by sentence
      const subChunks = chunkBySentence(trimmedPara, config);
      for (const subChunk of subChunks) {
        chunks.push({
          ...subChunk,
          index,
          startPos: textPos + subChunk.startPos,
          endPos: textPos + subChunk.endPos,
        });
        index++;
      }

      currentChunk = '';
      currentStart = textPos + trimmedPara.length;
    } else if (currentChunk.length + trimmedPara.length > maxChunkSize && currentChunk.length >= minChunkSize) {
      chunks.push({
        text: currentChunk.trim(),
        index,
        startPos: currentStart,
        endPos: textPos,
        length: currentChunk.length,
        tokenCount: Math.ceil(currentChunk.length / 4),
      });

      currentChunk = trimmedPara;
      currentStart = textPos;
      index++;
    } else {
      currentChunk += (currentChunk.length > 0 ? '\n\n' : '') + trimmedPara;
    }

    textPos += trimmedPara.length + 2; // +2 for paragraph break
  }

  // Add final chunk
  if (currentChunk.trim().length > 0) {
    chunks.push({
      text: currentChunk.trim(),
      index,
      startPos: currentStart,
      endPos: text.length,
      length: currentChunk.length,
      tokenCount: Math.ceil(currentChunk.length / 4),
    });
  }

  return chunks;
}

/**
 * Token-based chunking (approximate - uses chars/4 as estimate)
 */
function chunkByToken(
  text: string,
  config: Required<ChunkingConfig>
): Chunk[] {
  // Convert token limits to character limits (rough estimate: 1 token ≈ 4 chars)
  const charConfig: Required<ChunkingConfig> = {
    ...config,
    maxChunkSize: config.maxChunkSize * 4,
    overlap: config.overlap * 4,
    minChunkSize: config.minChunkSize * 4,
  };

  // Use sentence-aware chunking with converted limits
  return chunkBySentence(text, charConfig);
}

/**
 * Estimate token count for text
 */
export function estimateTokens(text: string): number {
  // Simple estimation: ~4 characters per token on average
  return Math.ceil(text.length / 4);
}

/**
 * Reconstruct original text from chunks (approximate)
 */
export function reconstructFromChunks(chunks: Chunk[]): string {
  if (chunks.length === 0) return '';
  if (chunks.length === 1) return chunks[0].text;

  // Sort by index
  const sorted = [...chunks].sort((a, b) => a.index - b.index);

  // Simple concatenation (overlap removal is approximate)
  let result = sorted[0].text;

  for (let i = 1; i < sorted.length; i++) {
    const chunk = sorted[i];
    const prevChunk = sorted[i - 1];

    // Find overlap by looking for common suffix/prefix
    const overlapSize = Math.min(100, prevChunk.text.length, chunk.text.length);
    const prevSuffix = prevChunk.text.slice(-overlapSize);
    const currPrefix = chunk.text.slice(0, overlapSize);

    // Find longest common overlap
    let overlap = 0;
    for (let len = overlapSize; len > 0; len--) {
      if (currPrefix.startsWith(prevSuffix.slice(-len))) {
        overlap = len;
        break;
      }
    }

    result += ' ' + chunk.text.slice(overlap);
  }

  return result.replace(/\s+/g, ' ').trim();
}

/**
 * V3 Embedding Service Implementation
 *
 * Production embedding service aligned with agentic-flow@alpha:
 * - OpenAI provider (text-embedding-3-small/large)
 * - Transformers.js provider (local ONNX models)
 * - Mock provider (development/testing)
 *
 * Performance Targets:
 * - Single embedding: <100ms (API), <50ms (local)
 * - Batch embedding: <500ms for 10 items
 * - Cache hit: <1ms
 */

import { EventEmitter } from 'events';
import type {
  EmbeddingProvider,
  EmbeddingConfig,
  OpenAIEmbeddingConfig,
  TransformersEmbeddingConfig,
  MockEmbeddingConfig,
  AgenticFlowEmbeddingConfig,
  RvfEmbeddingConfig,
  EmbeddingResult,
  BatchEmbeddingResult,
  IEmbeddingService,
  EmbeddingEvent,
  EmbeddingEventListener,
  SimilarityMetric,
  SimilarityResult,
  NormalizationType,
  PersistentCacheConfig,
} from './types.js';
import { normalize } from './normalization.js';
import { PersistentEmbeddingCache } from './persistent-cache.js';
import { RvfEmbeddingService } from './rvf-embedding-service.js';

// ============================================================================
// LRU Cache Implementation
// ============================================================================

class LRUCache<K, V> {
  private cache: Map<K, V> = new Map();
  private hits = 0;
  private misses = 0;

  constructor(private readonly maxSize: number) {}

  get(key: K): V | undefined {
    const value = this.cache.get(key);
    if (value !== undefined) {
      // Move to end (most recently used)
      this.cache.delete(key);
      this.cache.set(key, value);
      this.hits++;
      return value;
    }
    this.misses++;
    return undefined;
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.maxSize) {
      // Remove oldest (first) entry
      const firstKey = this.cache.keys().next().value;
      if (firstKey !== undefined) {
        this.cache.delete(firstKey);
      }
    }
    this.cache.set(key, value);
  }

  clear(): void {
    this.cache.clear();
    this.hits = 0;
    this.misses = 0;
  }

  get size(): number {
    return this.cache.size;
  }

  get hitRate(): number {
    const total = this.hits + this.misses;
    return total > 0 ? this.hits / total : 0;
  }

  getStats() {
    return {
      size: this.cache.size,
      maxSize: this.maxSize,
      hits: this.hits,
      misses: this.misses,
      hitRate: this.hitRate,
    };
  }
}

// ============================================================================
// Base Embedding Service
// ============================================================================

abstract class BaseEmbeddingService extends EventEmitter implements IEmbeddingService {
  abstract readonly provider: EmbeddingProvider;
  protected cache: LRUCache<string, Float32Array>;
  protected persistentCache: PersistentEmbeddingCache | null = null;
  protected embeddingListeners: Set<EmbeddingEventListener> = new Set();
  protected normalizationType: NormalizationType;

  constructor(protected readonly config: EmbeddingConfig) {
    super();
    this.cache = new LRUCache(config.cacheSize ?? 1000);
    this.normalizationType = config.normalization ?? 'none';

    // Initialize persistent cache if configured
    if (config.persistentCache?.enabled) {
      const pcConfig: PersistentCacheConfig = config.persistentCache;
      this.persistentCache = new PersistentEmbeddingCache({
        dbPath: pcConfig.dbPath ?? '.cache/embeddings.db',
        maxSize: pcConfig.maxSize ?? 10000,
        ttlMs: pcConfig.ttlMs,
      });
    }
  }

  abstract embed(text: string): Promise<EmbeddingResult>;
  abstract embedBatch(texts: string[]): Promise<BatchEmbeddingResult>;

  /**
   * Apply normalization to embedding if configured
   */
  protected applyNormalization(embedding: Float32Array): Float32Array {
    if (this.normalizationType === 'none') {
      return embedding;
    }
    return normalize(embedding, { type: this.normalizationType });
  }

  /**
   * Check persistent cache for embedding
   */
  protected async checkPersistentCache(text: string): Promise<Float32Array | null> {
    if (!this.persistentCache) return null;
    return this.persistentCache.get(text);
  }

  /**
   * Store embedding in persistent cache
   */
  protected async storePersistentCache(text: string, embedding: Float32Array): Promise<void> {
    if (!this.persistentCache) return;
    await this.persistentCache.set(text, embedding);
  }

  protected emitEvent(event: EmbeddingEvent): void {
    for (const listener of this.embeddingListeners) {
      try {
        listener(event);
      } catch (error) {
        console.error('Error in embedding event listener:', error);
      }
    }
    this.emit(event.type, event);
  }

  addEventListener(listener: EmbeddingEventListener): void {
    this.embeddingListeners.add(listener);
  }

  removeEventListener(listener: EmbeddingEventListener): void {
    this.embeddingListeners.delete(listener);
  }

  clearCache(): void {
    const size = this.cache.size;
    this.cache.clear();
    this.emitEvent({ type: 'cache_eviction', size });
  }

  getCacheStats() {
    const stats = this.cache.getStats();
    return {
      size: stats.size,
      maxSize: stats.maxSize,
      hitRate: stats.hitRate,
    };
  }

  async shutdown(): Promise<void> {
    this.clearCache();
    this.embeddingListeners.clear();
  }
}

// ============================================================================
// OpenAI Embedding Service
// ============================================================================

export class OpenAIEmbeddingService extends BaseEmbeddingService {
  readonly provider: EmbeddingProvider = 'openai';
  private readonly apiKey: string;
  private readonly model: string;
  private readonly baseURL: string;
  private readonly timeout: number;
  private readonly maxRetries: number;

  constructor(config: OpenAIEmbeddingConfig) {
    super(config);
    this.apiKey = config.apiKey;
    this.model = config.model ?? 'text-embedding-3-small';
    this.baseURL = config.baseURL ?? 'https://api.openai.com/v1/embeddings';
    this.timeout = config.timeout ?? 30000;
    this.maxRetries = config.maxRetries ?? 3;
  }

  async embed(text: string): Promise<EmbeddingResult> {
    // Check cache
    const cached = this.cache.get(text);
    if (cached) {
      this.emitEvent({ type: 'cache_hit', text });
      return {
        embedding: cached,
        latencyMs: 0,
        cached: true,
      };
    }

    this.emitEvent({ type: 'embed_start', text });
    const startTime = performance.now();

    try {
      const response = await this.callOpenAI([text]);
      const embedding = new Float32Array(response.data[0].embedding);

      // Cache result
      this.cache.set(text, embedding);

      const latencyMs = performance.now() - startTime;
      this.emitEvent({ type: 'embed_complete', text, latencyMs });

      return {
        embedding,
        latencyMs,
        usage: {
          promptTokens: response.usage?.prompt_tokens ?? 0,
          totalTokens: response.usage?.total_tokens ?? 0,
        },
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.emitEvent({ type: 'embed_error', text, error: message });
      throw new Error(`OpenAI embedding failed: ${message}`);
    }
  }

  async embedBatch(texts: string[]): Promise<BatchEmbeddingResult> {
    this.emitEvent({ type: 'batch_start', count: texts.length });
    const startTime = performance.now();

    // Check cache for each text
    const cached: Array<{ index: number; embedding: Float32Array }> = [];
    const uncached: Array<{ index: number; text: string }> = [];

    texts.forEach((text, index) => {
      const cachedEmbedding = this.cache.get(text);
      if (cachedEmbedding) {
        cached.push({ index, embedding: cachedEmbedding });
        this.emitEvent({ type: 'cache_hit', text });
      } else {
        uncached.push({ index, text });
      }
    });

    // Fetch uncached embeddings
    let apiEmbeddings: Float32Array[] = [];
    let usage = { promptTokens: 0, totalTokens: 0 };

    if (uncached.length > 0) {
      const response = await this.callOpenAI(uncached.map(u => u.text));
      apiEmbeddings = response.data.map(d => new Float32Array(d.embedding));

      // Cache results
      uncached.forEach((item, i) => {
        this.cache.set(item.text, apiEmbeddings[i]);
      });

      usage = {
        promptTokens: response.usage?.prompt_tokens ?? 0,
        totalTokens: response.usage?.total_tokens ?? 0,
      };
    }

    // Reconstruct result array in original order
    const embeddings: Array<Float32Array> = new Array(texts.length);
    cached.forEach(c => {
      embeddings[c.index] = c.embedding;
    });
    uncached.forEach((u, i) => {
      embeddings[u.index] = apiEmbeddings[i];
    });

    const totalLatencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'batch_complete', count: texts.length, latencyMs: totalLatencyMs });

    return {
      embeddings,
      totalLatencyMs,
      avgLatencyMs: totalLatencyMs / texts.length,
      usage,
      cacheStats: {
        hits: cached.length,
        misses: uncached.length,
      },
    };
  }

  private async callOpenAI(texts: string[]): Promise<{
    data: Array<{ embedding: number[] }>;
    usage?: { prompt_tokens: number; total_tokens: number };
  }> {
    const config = this.config as OpenAIEmbeddingConfig;

    for (let attempt = 0; attempt < this.maxRetries; attempt++) {
      try {
        const controller = new AbortController();
        const timeoutId = setTimeout(() => controller.abort(), this.timeout);

        const response = await fetch(this.baseURL, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${this.apiKey}`,
          },
          body: JSON.stringify({
            model: this.model,
            input: texts,
            dimensions: config.dimensions,
          }),
          signal: controller.signal,
        });

        clearTimeout(timeoutId);

        if (!response.ok) {
          const error = await response.text();
          throw new Error(`OpenAI API error: ${response.status} - ${error}`);
        }

        return await response.json() as {
          data: Array<{ embedding: number[] }>;
          usage?: { prompt_tokens: number; total_tokens: number };
        };
      } catch (error) {
        if (attempt === this.maxRetries - 1) {
          throw error;
        }
        // Exponential backoff
        await new Promise(resolve => setTimeout(resolve, Math.pow(2, attempt) * 100));
      }
    }

    throw new Error('Max retries exceeded');
  }
}

// ============================================================================
// Transformers.js Embedding Service
// ============================================================================

export class TransformersEmbeddingService extends BaseEmbeddingService {
  readonly provider: EmbeddingProvider = 'transformers';
  private pipeline: any = null;
  private readonly modelName: string;
  private initialized = false;

  constructor(config: TransformersEmbeddingConfig) {
    super(config);
    this.modelName = config.model ?? 'Xenova/all-MiniLM-L6-v2';
  }

  private async initialize(): Promise<void> {
    if (this.initialized) return;

    try {
      // ADR-094: try @huggingface/transformers first (clears the
      // protobufjs <7.5.5 critical RCE chain), fall back to legacy
      // @xenova/transformers for backwards compatibility.
      const { loadTransformersPipeline } = await import('./transformers-loader.js');
      const handle = await loadTransformersPipeline();
      if (!handle) {
        throw new Error(
          'No transformers package available. Install @huggingface/transformers (preferred) ' +
          'or @xenova/transformers to enable ONNX embeddings.',
        );
      }
      this.pipeline = await handle.pipeline('feature-extraction', this.modelName);
      this.initialized = true;
    } catch (error) {
      throw new Error(`Failed to initialize transformers pipeline: ${error}`);
    }
  }

  async embed(text: string): Promise<EmbeddingResult> {
    await this.initialize();

    // Check cache
    const cached = this.cache.get(text);
    if (cached) {
      this.emitEvent({ type: 'cache_hit', text });
      return {
        embedding: cached,
        latencyMs: 0,
        cached: true,
      };
    }

    this.emitEvent({ type: 'embed_start', text });
    const startTime = performance.now();

    try {
      const output = await this.pipeline(text, { pooling: 'mean', normalize: true });
      const embedding = new Float32Array(output.data);

      // Cache result
      this.cache.set(text, embedding);

      const latencyMs = performance.now() - startTime;
      this.emitEvent({ type: 'embed_complete', text, latencyMs });

      return {
        embedding,
        latencyMs,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.emitEvent({ type: 'embed_error', text, error: message });
      throw new Error(`Transformers.js embedding failed: ${message}`);
    }
  }

  async embedBatch(texts: string[]): Promise<BatchEmbeddingResult> {
    await this.initialize();

    this.emitEvent({ type: 'batch_start', count: texts.length });
    const startTime = performance.now();

    const embeddings: Float32Array[] = [];
    let cacheHits = 0;

    for (const text of texts) {
      const cached = this.cache.get(text);
      if (cached) {
        embeddings.push(cached);
        cacheHits++;
        this.emitEvent({ type: 'cache_hit', text });
      } else {
        const output = await this.pipeline(text, { pooling: 'mean', normalize: true });
        const embedding = new Float32Array(output.data);
        this.cache.set(text, embedding);
        embeddings.push(embedding);
      }
    }

    const totalLatencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'batch_complete', count: texts.length, latencyMs: totalLatencyMs });

    return {
      embeddings,
      totalLatencyMs,
      avgLatencyMs: totalLatencyMs / texts.length,
      cacheStats: {
        hits: cacheHits,
        misses: texts.length - cacheHits,
      },
    };
  }
}

// ============================================================================
// Mock Embedding Service
// ============================================================================

export class MockEmbeddingService extends BaseEmbeddingService {
  readonly provider: EmbeddingProvider = 'mock';
  private readonly dimensions: number;
  private readonly simulatedLatency: number;

  constructor(config: Partial<MockEmbeddingConfig> = {}) {
    const fullConfig: MockEmbeddingConfig = {
      provider: 'mock',
      dimensions: config.dimensions ?? 384,
      cacheSize: config.cacheSize ?? 1000,
      simulatedLatency: config.simulatedLatency ?? 0,
      enableCache: config.enableCache ?? true,
    };
    super(fullConfig);
    this.dimensions = fullConfig.dimensions!;
    this.simulatedLatency = fullConfig.simulatedLatency!;
  }

  async embed(text: string): Promise<EmbeddingResult> {
    // Check cache
    const cached = this.cache.get(text);
    if (cached) {
      this.emitEvent({ type: 'cache_hit', text });
      return {
        embedding: cached,
        latencyMs: 0,
        cached: true,
      };
    }

    this.emitEvent({ type: 'embed_start', text });
    const startTime = performance.now();

    // Simulate latency
    if (this.simulatedLatency > 0) {
      await new Promise(resolve => setTimeout(resolve, this.simulatedLatency));
    }

    const embedding = this.hashEmbedding(text);
    this.cache.set(text, embedding);

    const latencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'embed_complete', text, latencyMs });

    return {
      embedding,
      latencyMs,
    };
  }

  async embedBatch(texts: string[]): Promise<BatchEmbeddingResult> {
    this.emitEvent({ type: 'batch_start', count: texts.length });
    const startTime = performance.now();

    const embeddings: Float32Array[] = [];
    let cacheHits = 0;

    for (const text of texts) {
      const cached = this.cache.get(text);
      if (cached) {
        embeddings.push(cached);
        cacheHits++;
      } else {
        const embedding = this.hashEmbedding(text);
        this.cache.set(text, embedding);
        embeddings.push(embedding);
      }
    }

    const totalLatencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'batch_complete', count: texts.length, latencyMs: totalLatencyMs });

    return {
      embeddings,
      totalLatencyMs,
      avgLatencyMs: totalLatencyMs / texts.length,
      cacheStats: {
        hits: cacheHits,
        misses: texts.length - cacheHits,
      },
    };
  }

  /**
   * Generate deterministic hash-based embedding
   */
  private hashEmbedding(text: string): Float32Array {
    const embedding = new Float32Array(this.dimensions);

    // Seed with text hash
    let hash = 0;
    for (let i = 0; i < text.length; i++) {
      hash = (hash << 5) - hash + text.charCodeAt(i);
      hash = hash & hash;
    }

    // Generate pseudo-random embedding
    for (let i = 0; i < this.dimensions; i++) {
      const seed = hash + i * 2654435761;
      const x = Math.sin(seed) * 10000;
      embedding[i] = x - Math.floor(x);
    }

    // Normalize to unit vector
    const norm = Math.sqrt(embedding.reduce((sum, v) => sum + v * v, 0));
    for (let i = 0; i < this.dimensions; i++) {
      embedding[i] /= norm;
    }

    return embedding;
  }
}

// ============================================================================
// Agentic-Flow Embedding Service
// ============================================================================

/**
 * Agentic-Flow embedding service using OptimizedEmbedder
 *
 * Features:
 * - ONNX-based embeddings with SIMD acceleration
 * - 256-entry LRU cache with FNV-1a hash
 * - 8x loop unrolling for cosine similarity
 * - Pre-allocated buffers (no GC pressure)
 * - 3-4x faster batch processing
 */
export class AgenticFlowEmbeddingService extends BaseEmbeddingService {
  readonly provider: EmbeddingProvider = 'agentic-flow';
  private embedder: any = null;
  private initialized = false;
  private readonly modelId: string;
  private readonly dimensions: number;
  private readonly embedderCacheSize: number;
  private readonly modelDir: string | undefined;
  private readonly autoDownload: boolean;

  constructor(config: AgenticFlowEmbeddingConfig) {
    super(config);
    this.modelId = config.modelId ?? 'all-MiniLM-L6-v2';
    this.dimensions = config.dimensions ?? 384;
    this.embedderCacheSize = config.embedderCacheSize ?? 256;
    this.modelDir = config.modelDir;
    this.autoDownload = config.autoDownload ?? false;
  }

  private async initialize(): Promise<void> {
    if (this.initialized) return;

    let lastError: Error | undefined;

    const createEmbedder = async (modulePath: string): Promise<boolean> => {
      try {
        // Use file:// protocol for absolute paths
        const importPath = modulePath.startsWith('/') ? `file://${modulePath}` : modulePath;
        const module = await import(/* webpackIgnore: true */ importPath);
        const getOptimizedEmbedder = module.getOptimizedEmbedder || module.default?.getOptimizedEmbedder;
        if (!getOptimizedEmbedder) {
          lastError = new Error(`Module loaded but getOptimizedEmbedder not found`);
          return false;
        }

        // Only include defined values to not override defaults
        const embedderConfig: Record<string, unknown> = {
          modelId: this.modelId,
          dimension: this.dimensions,
          cacheSize: this.embedderCacheSize,
          autoDownload: this.autoDownload,
        };
        if (this.modelDir !== undefined) {
          embedderConfig.modelDir = this.modelDir;
        }
        this.embedder = getOptimizedEmbedder(embedderConfig);
        await this.embedder.init();
        this.initialized = true;
        return true;
      } catch (error) {
        lastError = error instanceof Error ? error : new Error(String(error));
        return false;
      }
    };

    // Build list of possible module paths to try
    const possiblePaths: string[] = [];

    // Try proper package exports first (preferred)
    possiblePaths.push('agentic-flow/embeddings');

    // Try node_modules resolution from different locations (for file:// imports)
    try {
      const path = await import('path');
      const { existsSync } = await import('fs');
      const cwd = process.cwd();

      // Prioritize absolute paths that exist (for file:// import fallback)
      const absolutePaths = [
        path.join(cwd, 'node_modules/agentic-flow/dist/embeddings/optimized-embedder.js'),
        path.join(cwd, '../node_modules/agentic-flow/dist/embeddings/optimized-embedder.js'),
        '/workspaces/claude-flow/node_modules/agentic-flow/dist/embeddings/optimized-embedder.js',
      ];

      for (const p of absolutePaths) {
        if (existsSync(p)) {
          possiblePaths.push(p);
        }
      }
    } catch {
      // fs/path module not available
    }

    // Try each path
    for (const modulePath of possiblePaths) {
      if (await createEmbedder(modulePath)) {
        return;
      }
    }

    const errorDetail = lastError?.message ? ` Last error: ${lastError.message}` : '';
    throw new Error(
      `Failed to initialize agentic-flow embeddings.${errorDetail} ` +
      `Ensure agentic-flow is installed and ONNX model is downloaded: ` +
      `npx agentic-flow@alpha embeddings init`
    );
  }

  async embed(text: string): Promise<EmbeddingResult> {
    await this.initialize();

    // Check our LRU cache first
    const cached = this.cache.get(text);
    if (cached) {
      this.emitEvent({ type: 'cache_hit', text });
      return {
        embedding: cached,
        latencyMs: 0,
        cached: true,
      };
    }

    this.emitEvent({ type: 'embed_start', text });
    const startTime = performance.now();

    try {
      // Use agentic-flow's optimized embedder (has its own internal cache)
      const embedding = await this.embedder.embed(text);

      // Store in our cache as well
      this.cache.set(text, embedding);

      const latencyMs = performance.now() - startTime;
      this.emitEvent({ type: 'embed_complete', text, latencyMs });

      return {
        embedding,
        latencyMs,
      };
    } catch (error) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      this.emitEvent({ type: 'embed_error', text, error: message });
      throw new Error(`Agentic-flow embedding failed: ${message}`);
    }
  }

  async embedBatch(texts: string[]): Promise<BatchEmbeddingResult> {
    await this.initialize();

    this.emitEvent({ type: 'batch_start', count: texts.length });
    const startTime = performance.now();

    // Check cache for each text
    const cached: Array<{ index: number; embedding: Float32Array }> = [];
    const uncached: Array<{ index: number; text: string }> = [];

    texts.forEach((text, index) => {
      const cachedEmbedding = this.cache.get(text);
      if (cachedEmbedding) {
        cached.push({ index, embedding: cachedEmbedding });
        this.emitEvent({ type: 'cache_hit', text });
      } else {
        uncached.push({ index, text });
      }
    });

    // Use optimized batch embedding for uncached texts
    let batchEmbeddings: Float32Array[] = [];
    if (uncached.length > 0) {
      const uncachedTexts = uncached.map(u => u.text);
      batchEmbeddings = await this.embedder.embedBatch(uncachedTexts);

      // Cache results
      uncached.forEach((item, i) => {
        this.cache.set(item.text, batchEmbeddings[i]);
      });
    }

    // Reconstruct result array in original order
    const embeddings: Float32Array[] = new Array(texts.length);
    cached.forEach(c => {
      embeddings[c.index] = c.embedding;
    });
    uncached.forEach((u, i) => {
      embeddings[u.index] = batchEmbeddings[i];
    });

    const totalLatencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'batch_complete', count: texts.length, latencyMs: totalLatencyMs });

    return {
      embeddings,
      totalLatencyMs,
      avgLatencyMs: totalLatencyMs / texts.length,
      cacheStats: {
        hits: cached.length,
        misses: uncached.length,
      },
    };
  }

  /**
   * Get combined cache statistics from both our LRU cache and embedder's internal cache
   */
  override getCacheStats() {
    const baseStats = super.getCacheStats();

    if (this.embedder && this.embedder.getCacheStats) {
      const embedderStats = this.embedder.getCacheStats();
      return {
        size: baseStats.size + embedderStats.size,
        maxSize: baseStats.maxSize + embedderStats.maxSize,
        hitRate: baseStats.hitRate,
        embedderCache: embedderStats,
      };
    }

    return baseStats;
  }

  override async shutdown(): Promise<void> {
    if (this.embedder && this.embedder.clearCache) {
      this.embedder.clearCache();
    }
    await super.shutdown();
  }
}

// ============================================================================
// Factory Functions
// ============================================================================

/**
 * Check if agentic-flow is available
 */
async function isAgenticFlowAvailable(): Promise<boolean> {
  try {
    await import('agentic-flow/embeddings');
    return true;
  } catch {
    return false;
  }
}

/**
 * Auto-install agentic-flow and initialize model
 */
async function autoInstallAgenticFlow(): Promise<boolean> {
  const { exec } = await import('child_process');
  const { promisify } = await import('util');
  const execAsync = promisify(exec);

  try {
    // Check if already available
    if (await isAgenticFlowAvailable()) {
      return true;
    }

    console.log('[embeddings] Installing agentic-flow@alpha...');
    await execAsync('npm install agentic-flow@alpha --save', { timeout: 120000 });

    // Initialize the model
    console.log('[embeddings] Downloading embedding model...');
    await execAsync('npx agentic-flow@alpha embeddings init', { timeout: 300000 });

    // Verify installation
    return await isAgenticFlowAvailable();
  } catch (error) {
    console.warn('[embeddings] Auto-install failed:', error instanceof Error ? error.message : error);
    return false;
  }
}

/**
 * Create embedding service based on configuration (sync version)
 * Note: For 'auto' provider or smart fallback, use createEmbeddingServiceAsync
 */
export function createEmbeddingService(config: EmbeddingConfig): IEmbeddingService {
  switch (config.provider) {
    case 'openai':
      return new OpenAIEmbeddingService(config as OpenAIEmbeddingConfig);
    case 'transformers':
      return new TransformersEmbeddingService(config as TransformersEmbeddingConfig);
    case 'mock':
      return new MockEmbeddingService(config as MockEmbeddingConfig);
    case 'agentic-flow':
      return new AgenticFlowEmbeddingService(config as AgenticFlowEmbeddingConfig);
    case 'rvf':
      return new RvfEmbeddingService(config as RvfEmbeddingConfig);
    default:
      throw new Error(
        `Unknown embedding provider: '${(config as EmbeddingConfig).provider}'. ` +
        `Use 'agentic-flow' (recommended), 'transformers', 'openai', 'rvf', or 'mock' (tests only).`
      );
  }
}

/**
 * Extended config with auto provider option
 */
export interface AutoEmbeddingConfig {
  /** Provider: 'auto' will pick best available (agentic-flow > transformers > mock) */
  provider: EmbeddingProvider | 'auto';
  /** Fallback provider if primary fails */
  fallback?: EmbeddingProvider;
  /** Auto-install agentic-flow if not available (default: true for 'auto' provider) */
  autoInstall?: boolean;
  /** Model ID for agentic-flow */
  modelId?: string;
  /** Model name for transformers */
  model?: string;
  /** Dimensions */
  dimensions?: number;
  /** Cache size */
  cacheSize?: number;
  /** OpenAI API key (required for openai provider) */
  apiKey?: string;
}

/**
 * Create embedding service with automatic provider detection and fallback
 *
 * Features:
 * - 'auto' provider picks best available: agentic-flow > transformers > mock
 * - Automatic fallback if primary provider fails to initialize
 * - Pre-validates provider availability before returning
 *
 * @example
 * // Auto-select best provider
 * const service = await createEmbeddingServiceAsync({ provider: 'auto' });
 *
 * // Try agentic-flow, fallback to transformers
 * const service = await createEmbeddingServiceAsync({
 *   provider: 'agentic-flow',
 *   fallback: 'transformers'
 * });
 */
export async function createEmbeddingServiceAsync(
  config: AutoEmbeddingConfig
): Promise<IEmbeddingService> {
  const { provider, fallback, autoInstall = true, ...rest } = config;

  // Auto provider selection
  if (provider === 'auto') {
    // Try RVF first (52KB, always available, fast hash embeddings)
    try {
      const service = new RvfEmbeddingService({
        provider: 'rvf',
        dimensions: rest.dimensions ?? 384,
        cacheSize: rest.cacheSize,
      });
      await service.embed('test');
      return service;
    } catch { /* fall through */ }

    // Try agentic-flow (fastest neural, ONNX-based)
    let agenticFlowAvailable = await isAgenticFlowAvailable();

    // Auto-install if not available and autoInstall is enabled
    if (!agenticFlowAvailable && autoInstall) {
      agenticFlowAvailable = await autoInstallAgenticFlow();
    }

    if (agenticFlowAvailable) {
      try {
        const service = new AgenticFlowEmbeddingService({
          provider: 'agentic-flow',
          modelId: rest.modelId ?? 'all-MiniLM-L6-v2',
          dimensions: rest.dimensions ?? 384,
          cacheSize: rest.cacheSize,
        });
        // Validate it can initialize
        await service.embed('test');
        return service;
      } catch {
        // Fall through to next option
      }
    }

    // Try transformers (good quality, built-in)
    try {
      const service = new TransformersEmbeddingService({
        provider: 'transformers',
        model: rest.model ?? 'Xenova/all-MiniLM-L6-v2',
        cacheSize: rest.cacheSize,
      });
      // Validate it can initialize
      await service.embed('test');
      return service;
    } catch {
      // Fall through to mock
    }

    // No real provider available — refuse to silently fall back to mock embeddings.
    throw new Error(
      "[embeddings] No real embedding provider available for 'auto'. " +
      'Install agentic-flow OR @xenova/transformers, OR pass provider:"openai" with apiKey, ' +
      'OR explicitly request provider:"mock" if mock embeddings are intentional (tests only).'
    );
  }

  // Specific provider with optional fallback
  const createPrimary = (): IEmbeddingService => {
    switch (provider) {
      case 'agentic-flow':
        return new AgenticFlowEmbeddingService({
          provider: 'agentic-flow',
          modelId: rest.modelId ?? 'all-MiniLM-L6-v2',
          dimensions: rest.dimensions ?? 384,
          cacheSize: rest.cacheSize,
        });
      case 'transformers':
        return new TransformersEmbeddingService({
          provider: 'transformers',
          model: rest.model ?? 'Xenova/all-MiniLM-L6-v2',
          cacheSize: rest.cacheSize,
        });
      case 'openai':
        if (!rest.apiKey) throw new Error('OpenAI provider requires apiKey');
        return new OpenAIEmbeddingService({
          provider: 'openai',
          apiKey: rest.apiKey,
          dimensions: rest.dimensions,
          cacheSize: rest.cacheSize,
        });
      case 'rvf':
        return new RvfEmbeddingService({
          provider: 'rvf',
          dimensions: rest.dimensions ?? 384,
          cacheSize: rest.cacheSize,
        });
      case 'mock':
        return new MockEmbeddingService({
          dimensions: rest.dimensions ?? 384,
          cacheSize: rest.cacheSize,
        });
      default:
        throw new Error(`Unknown provider: ${provider}`);
    }
  };

  const primary = createPrimary();

  // Try to validate primary provider
  try {
    await primary.embed('test');
    return primary;
  } catch (error) {
    if (!fallback) {
      throw error;
    }

    // Try fallback
    console.warn(`[embeddings] Primary provider '${provider}' failed, using fallback '${fallback}'`);
    const fallbackConfig: AutoEmbeddingConfig = { ...rest, provider: fallback };
    return createEmbeddingServiceAsync(fallbackConfig);
  }
}

/**
 * Convenience function for quick embeddings
 */
export async function getEmbedding(
  text: string,
  config?: Partial<EmbeddingConfig>
): Promise<Float32Array | number[]> {
  const service = createEmbeddingService({
    provider: 'mock',
    dimensions: 384,
    ...config,
  } as EmbeddingConfig);

  try {
    const result = await service.embed(text);
    return result.embedding;
  } finally {
    await service.shutdown();
  }
}

// ============================================================================
// Similarity Functions
// ============================================================================

/**
 * Compute cosine similarity between two embeddings
 */
export function cosineSimilarity(
  a: Float32Array | number[],
  b: Float32Array | number[]
): number {
  if (a.length !== b.length) {
    throw new Error('Embedding dimensions must match');
  }

  let dot = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    normA += a[i] * a[i];
    normB += b[i] * b[i];
  }

  const denom = Math.sqrt(normA) * Math.sqrt(normB);
  return denom > 0 ? dot / denom : 0;
}

/**
 * Compute Euclidean distance between two embeddings
 */
export function euclideanDistance(
  a: Float32Array | number[],
  b: Float32Array | number[]
): number {
  if (a.length !== b.length) {
    throw new Error('Embedding dimensions must match');
  }

  let sum = 0;
  for (let i = 0; i < a.length; i++) {
    const diff = a[i] - b[i];
    sum += diff * diff;
  }

  return Math.sqrt(sum);
}

/**
 * Compute dot product between two embeddings
 */
export function dotProduct(
  a: Float32Array | number[],
  b: Float32Array | number[]
): number {
  if (a.length !== b.length) {
    throw new Error('Embedding dimensions must match');
  }

  let dot = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
  }

  return dot;
}

/**
 * Compute similarity using specified metric
 */
export function computeSimilarity(
  a: Float32Array | number[],
  b: Float32Array | number[],
  metric: SimilarityMetric = 'cosine'
): SimilarityResult {
  switch (metric) {
    case 'cosine':
      return { score: cosineSimilarity(a, b), metric };
    case 'euclidean':
      // Convert distance to similarity (closer = higher score)
      return { score: 1 / (1 + euclideanDistance(a, b)), metric };
    case 'dot':
      return { score: dotProduct(a, b), metric };
    default:
      return { score: cosineSimilarity(a, b), metric: 'cosine' };
  }
}

/**
 * Hyperbolic Embedding Utilities
 *
 * Convert Euclidean embeddings to hyperbolic (Poincaré ball) space
 * for better representation of hierarchical relationships.
 *
 * Features:
 * - Euclidean to Poincaré ball conversion
 * - Hyperbolic distance metrics
 * - Mobius operations (addition, scalar multiplication)
 * - Exponential and logarithmic maps
 *
 * References:
 * - Nickel & Kiela (2017): "Poincaré Embeddings for Learning Hierarchical Representations"
 * - Ganea et al. (2018): "Hyperbolic Neural Networks"
 */

/**
 * Hyperbolic geometry configuration
 */
export interface HyperbolicConfig {
  /** Curvature of hyperbolic space (default: -1) */
  curvature?: number;
  /** Epsilon for numerical stability (default: 1e-15) */
  epsilon?: number;
  /** Maximum norm to prevent numerical issues (default: 1 - 1e-5) */
  maxNorm?: number;
}

const DEFAULT_CONFIG: Required<HyperbolicConfig> = {
  curvature: -1,
  epsilon: 1e-15,
  maxNorm: 1 - 1e-5,
};

/**
 * Compute L2 norm of vector
 */
function l2Norm(v: Float32Array | number[]): number {
  let sum = 0;
  for (let i = 0; i < v.length; i++) {
    sum += v[i] * v[i];
  }
  return Math.sqrt(sum);
}

/**
 * Clamp vector norm to stay within Poincaré ball
 */
function clampNorm(
  v: Float32Array,
  maxNorm: number,
  epsilon: number
): Float32Array {
  const norm = l2Norm(v);
  if (norm > maxNorm) {
    const scale = (maxNorm - epsilon) / norm;
    for (let i = 0; i < v.length; i++) {
      v[i] *= scale;
    }
  }
  return v;
}

/**
 * Convert Euclidean embedding to Poincaré ball
 *
 * Uses exponential map at origin to project Euclidean vectors
 * into the Poincaré ball model of hyperbolic space.
 *
 * @param euclidean - Euclidean embedding vector
 * @param config - Hyperbolic geometry configuration
 * @returns Poincaré ball embedding
 */
export function euclideanToPoincare(
  euclidean: Float32Array | number[],
  config: HyperbolicConfig = {}
): Float32Array {
  const { curvature, epsilon, maxNorm } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);
  const sqrtC = Math.sqrt(c);

  const result = new Float32Array(euclidean.length);
  const norm = l2Norm(euclidean);

  if (norm < epsilon) {
    // Near origin, return as-is (origin maps to origin)
    for (let i = 0; i < euclidean.length; i++) {
      result[i] = euclidean[i];
    }
    return result;
  }

  // Exponential map at origin: exp_0(v) = tanh(sqrt(c) * ||v|| / 2) * v / (sqrt(c) * ||v||)
  const factor = Math.tanh(sqrtC * norm / 2) / (sqrtC * norm);

  for (let i = 0; i < euclidean.length; i++) {
    result[i] = euclidean[i] * factor;
  }

  return clampNorm(result, maxNorm, epsilon);
}

/**
 * Convert Poincaré ball embedding back to Euclidean
 *
 * Uses logarithmic map at origin to project back to Euclidean space.
 *
 * @param poincare - Poincaré ball embedding
 * @param config - Hyperbolic geometry configuration
 * @returns Euclidean embedding vector
 */
export function poincareToEuclidean(
  poincare: Float32Array | number[],
  config: HyperbolicConfig = {}
): Float32Array {
  const { curvature, epsilon } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);
  const sqrtC = Math.sqrt(c);

  const result = new Float32Array(poincare.length);
  const norm = l2Norm(poincare);

  if (norm < epsilon) {
    for (let i = 0; i < poincare.length; i++) {
      result[i] = poincare[i];
    }
    return result;
  }

  // Logarithmic map at origin: log_0(y) = 2 * arctanh(sqrt(c) * ||y||) * y / (sqrt(c) * ||y||)
  const factor = 2 * Math.atanh(sqrtC * norm) / (sqrtC * norm);

  for (let i = 0; i < poincare.length; i++) {
    result[i] = poincare[i] * factor;
  }

  return result;
}

/**
 * Compute hyperbolic distance in Poincaré ball
 *
 * The geodesic distance between two points in the Poincaré ball.
 *
 * @param a - First Poincaré embedding
 * @param b - Second Poincaré embedding
 * @param config - Hyperbolic geometry configuration
 * @returns Hyperbolic distance
 */
export function hyperbolicDistance(
  a: Float32Array | number[],
  b: Float32Array | number[],
  config: HyperbolicConfig = {}
): number {
  const { curvature, epsilon } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);
  const sqrtC = Math.sqrt(c);

  if (a.length !== b.length) {
    throw new Error('Embeddings must have same dimension');
  }

  // ||a - b||^2
  let diffNormSq = 0;
  for (let i = 0; i < a.length; i++) {
    const d = a[i] - b[i];
    diffNormSq += d * d;
  }

  // ||a||^2 and ||b||^2
  let normASq = 0;
  let normBSq = 0;
  for (let i = 0; i < a.length; i++) {
    normASq += a[i] * a[i];
    normBSq += b[i] * b[i];
  }

  // Poincaré distance formula:
  // d(a, b) = (1/sqrt(c)) * arcosh(1 + 2c * ||a-b||^2 / ((1 - c*||a||^2)(1 - c*||b||^2)))
  const numerator = 2 * c * diffNormSq;
  const denominator = (1 - c * normASq) * (1 - c * normBSq);

  // Clamp to prevent numerical issues
  const arg = Math.max(1, 1 + numerator / Math.max(denominator, epsilon));

  return Math.acosh(arg) / sqrtC;
}

/**
 * Möbius addition in Poincaré ball
 *
 * Hyperbolic "addition" operation that respects the ball geometry.
 *
 * @param a - First vector
 * @param b - Second vector
 * @param config - Configuration
 * @returns a ⊕ b in hyperbolic space
 */
export function mobiusAdd(
  a: Float32Array | number[],
  b: Float32Array | number[],
  config: HyperbolicConfig = {}
): Float32Array {
  const { curvature, epsilon, maxNorm } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);

  if (a.length !== b.length) {
    throw new Error('Vectors must have same dimension');
  }

  let normASq = 0;
  let normBSq = 0;
  for (let i = 0; i < a.length; i++) {
    normASq += a[i] * a[i];
    normBSq += b[i] * b[i];
  }

  // <a, b>
  let dotAB = 0;
  for (let i = 0; i < a.length; i++) {
    dotAB += a[i] * b[i];
  }

  // Möbius addition formula
  const numeratorCoeffA = 1 + 2 * c * dotAB + c * normBSq;
  const numeratorCoeffB = 1 - c * normASq;
  const denominator = 1 + 2 * c * dotAB + c * c * normASq * normBSq;

  const result = new Float32Array(a.length);
  for (let i = 0; i < a.length; i++) {
    result[i] = (numeratorCoeffA * a[i] + numeratorCoeffB * b[i]) / Math.max(denominator, epsilon);
  }

  return clampNorm(result, maxNorm, epsilon);
}

/**
 * Möbius scalar multiplication in Poincaré ball
 *
 * @param r - Scalar
 * @param v - Vector in Poincaré ball
 * @param config - Configuration
 * @returns r ⊗ v in hyperbolic space
 */
export function mobiusScalarMul(
  r: number,
  v: Float32Array | number[],
  config: HyperbolicConfig = {}
): Float32Array {
  const { curvature, epsilon, maxNorm } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);
  const sqrtC = Math.sqrt(c);

  const norm = l2Norm(v);

  if (norm < epsilon) {
    return new Float32Array(v.length);
  }

  // r ⊗ v = tanh(r * arctanh(sqrt(c) * ||v||)) * v / (sqrt(c) * ||v||)
  const factor = Math.tanh(r * Math.atanh(sqrtC * norm)) / (sqrtC * norm);

  const result = new Float32Array(v.length);
  for (let i = 0; i < v.length; i++) {
    result[i] = v[i] * factor;
  }

  return clampNorm(result, maxNorm, epsilon);
}

/**
 * Compute hyperbolic centroid (Fréchet mean) of multiple points
 *
 * Uses iterative optimization to find the centroid in Poincaré ball.
 *
 * @param points - Array of Poincaré embeddings
 * @param config - Configuration
 * @param maxIter - Maximum iterations (default: 100)
 * @returns Hyperbolic centroid
 */
export function hyperbolicCentroid(
  points: Array<Float32Array | number[]>,
  config: HyperbolicConfig = {},
  maxIter = 100
): Float32Array {
  if (points.length === 0) {
    throw new Error('Need at least one point');
  }
  if (points.length === 1) {
    const arr = new Float32Array(points[0].length);
    for (let i = 0; i < points[0].length; i++) {
      arr[i] = points[0][i];
    }
    return arr;
  }

  const { epsilon } = { ...DEFAULT_CONFIG, ...config };
  const dim = points[0].length;

  // Initialize centroid at Euclidean mean projected to ball
  const centroidInit = new Float32Array(dim);
  for (const p of points) {
    for (let i = 0; i < dim; i++) {
      centroidInit[i] += p[i];
    }
  }
  for (let i = 0; i < dim; i++) {
    centroidInit[i] /= points.length;
  }

  // Project to Poincaré ball
  const projectedInit = euclideanToPoincare(centroidInit, config);
  let centroid = new Float32Array(dim);
  for (let i = 0; i < dim; i++) {
    centroid[i] = projectedInit[i];
  }

  // Iterative refinement using Karcher mean algorithm
  for (let iter = 0; iter < maxIter; iter++) {
    const gradient = new Float32Array(dim);

    for (const p of points) {
      // Log map from centroid to point
      const pArr = p instanceof Float32Array ? p : new Float32Array(p);
      const logMap = logMapAt(centroid, pArr, config);
      for (let i = 0; i < dim; i++) {
        gradient[i] += logMap[i];
      }
    }

    // Check convergence
    const gradNorm = l2Norm(gradient);
    if (gradNorm < epsilon) break;

    // Update centroid using exponential map
    for (let i = 0; i < dim; i++) {
      gradient[i] /= points.length;
    }
    const updated = expMapAt(centroid, gradient, config);
    for (let i = 0; i < dim; i++) {
      centroid[i] = updated[i];
    }
  }

  return centroid;
}

/**
 * Exponential map at point p
 */
function expMapAt(
  p: Float32Array,
  v: Float32Array,
  config: HyperbolicConfig = {}
): Float32Array {
  const { curvature, epsilon, maxNorm } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);

  const normP = l2Norm(p);
  const lambdaP = 2 / (1 - c * normP * normP);
  const normV = l2Norm(v);

  if (normV < epsilon) {
    return new Float32Array(p);
  }

  const sqrtC = Math.sqrt(c);
  const tanhArg = sqrtC * lambdaP * normV / 2;
  const coeff = Math.tanh(tanhArg) / (sqrtC * normV);

  const scaledV = new Float32Array(v.length);
  for (let i = 0; i < v.length; i++) {
    scaledV[i] = v[i] * coeff;
  }

  return clampNorm(mobiusAdd(p, scaledV, config), maxNorm, epsilon);
}

/**
 * Logarithmic map at point p
 */
function logMapAt(
  p: Float32Array,
  q: Float32Array,
  config: HyperbolicConfig = {}
): Float32Array {
  const { curvature, epsilon } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);
  const sqrtC = Math.sqrt(c);

  // -p ⊕ q
  const negP = new Float32Array(p.length);
  for (let i = 0; i < p.length; i++) {
    negP[i] = -p[i];
  }
  const diff = mobiusAdd(negP, q, config);

  const normP = l2Norm(p);
  const normDiff = l2Norm(diff);
  const lambdaP = 2 / (1 - c * normP * normP);

  if (normDiff < epsilon) {
    return new Float32Array(p.length);
  }

  const coeff = (2 / (sqrtC * lambdaP)) * Math.atanh(sqrtC * normDiff) / normDiff;

  const result = new Float32Array(diff.length);
  for (let i = 0; i < diff.length; i++) {
    result[i] = diff[i] * coeff;
  }

  return result;
}

/**
 * Batch convert Euclidean embeddings to Poincaré ball
 */
export function batchEuclideanToPoincare(
  embeddings: Array<Float32Array | number[]>,
  config: HyperbolicConfig = {}
): Float32Array[] {
  return embeddings.map(e => euclideanToPoincare(e, config));
}

/**
 * Compute pairwise hyperbolic distances
 */
export function pairwiseHyperbolicDistances(
  embeddings: Float32Array[],
  config: HyperbolicConfig = {}
): Float32Array {
  const n = embeddings.length;
  const distances = new Float32Array((n * (n - 1)) / 2);

  let idx = 0;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      distances[idx++] = hyperbolicDistance(embeddings[i], embeddings[j], config);
    }
  }

  return distances;
}

/**
 * Check if point is inside Poincaré ball
 */
export function isInPoincareBall(
  v: Float32Array | number[],
  config: HyperbolicConfig = {}
): boolean {
  const { curvature } = { ...DEFAULT_CONFIG, ...config };
  const c = Math.abs(curvature);
  const norm = l2Norm(v);
  return norm < 1 / Math.sqrt(c);
}

