 * Integrates agentic-flow's neural embedding features:
 * - Semantic drift detection
 * - Memory physics (hippocampal dynamics)
 * - Embedding state machine
 * - Swarm coordination
 * - Coherence monitoring
 *
 * These features treat embeddings as a synthetic nervous system.
 */

// Types from agentic-flow/embeddings
export interface DriftResult {
  distance: number;
  velocity: number;
  acceleration: number;
  trend: 'stable' | 'drifting' | 'accelerating' | 'recovering';
  shouldEscalate: boolean;
  shouldTriggerReasoning: boolean;
}

export interface MemoryEntry {
  id: string;
  embedding: Float32Array;
  content: string;
  strength: number;
  timestamp: number;
  accessCount: number;
  associations: string[];
}

export interface AgentState {
  id: string;
  position: Float32Array;
  velocity: Float32Array;
  attention: Float32Array;
  energy: number;
  lastUpdate: number;
}

export interface CoherenceResult {
  isCoherent: boolean;
  anomalyScore: number;
  stabilityScore: number;
  driftDirection: Float32Array | null;
  warnings: string[];
}

export interface SubstrateHealth {
  memoryCount: number;
  activeAgents: number;
  avgDrift: number;
  avgCoherence: number;
  lastConsolidation: number;
  uptime: number;
}

export interface NeuralSubstrateConfig {
  dimension?: number;
  driftThreshold?: number;
  decayRate?: number;
}

/**
 * Lazy-loaded Neural Substrate wrapper
 *
 * Wraps agentic-flow's NeuralSubstrate with graceful fallback
 */
export class NeuralEmbeddingService {
  private substrate: any = null;
  private initialized = false;
  private available = false;

  constructor(private config: NeuralSubstrateConfig = {}) {}

  /**
   * Initialize neural substrate
   */
  async init(): Promise<boolean> {
    if (this.initialized) return this.available;

    try {
      const { getNeuralSubstrate } = await import('agentic-flow/embeddings');
      this.substrate = await getNeuralSubstrate(this.config);
      await this.substrate.init();
      this.available = true;
    } catch (error) {
      console.warn('[neural] Neural substrate not available:', error instanceof Error ? error.message : error);
      this.available = false;
    }

    this.initialized = true;
    return this.available;
  }

  /**
   * Check if neural features are available
   */
  isAvailable(): boolean {
    return this.available;
  }

  /**
   * Detect semantic drift from baseline
   */
  async detectDrift(input: string): Promise<DriftResult | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.drift.detect(input);
  }

  /**
   * Set baseline for drift detection
   */
  async setDriftBaseline(context: string): Promise<void> {
    if (!this.available || !this.substrate) return;
    await this.substrate.drift.setBaseline(context);
  }

  /**
   * Store memory with interference detection
   */
  async storeMemory(id: string, content: string): Promise<{ stored: boolean; interference: string[] } | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.memory.store(id, content);
  }

  /**
   * Recall memories by similarity
   */
  async recallMemories(query: string, topK = 5): Promise<Array<MemoryEntry & { relevance: number }> | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.memory.recall(query, topK);
  }

  /**
   * Consolidate memories (merge similar, forget weak)
   */
  consolidateMemories(): { merged: number; forgotten: number; remaining: number } | null {
    if (!this.available || !this.substrate) return null;
    return this.substrate.memory.consolidate();
  }

  /**
   * Register agent for state tracking
   */
  async registerAgent(id: string, role: string): Promise<AgentState | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.states.registerAgent(id, role);
  }

  /**
   * Update agent state based on observation
   */
  async updateAgentState(agentId: string, observation: string): Promise<{
    newState: AgentState;
    nearestRegion: string;
    regionProximity: number;
  } | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.states.updateState(agentId, observation);
  }

  /**
   * Get agent state
   */
  getAgentState(agentId: string): AgentState | null {
    if (!this.available || !this.substrate) return null;
    return this.substrate.states.getAgent(agentId);
  }

  /**
   * Coordinate swarm for task
   */
  async coordinateSwarm(task: string): Promise<Array<{
    agentId: string;
    taskAlignment: number;
    bestCollaborator: string | null;
    collaborationScore: number;
  }> | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.swarm.coordinate(task);
  }

  /**
   * Add agent to swarm
   */
  async addSwarmAgent(id: string, role: string): Promise<AgentState | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.swarm.addAgent(id, role);
  }

  /**
   * Calibrate coherence monitor
   */
  async calibrateCoherence(goodOutputs: string[]): Promise<{ calibrated: boolean; sampleCount: number } | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.coherence.calibrate(goodOutputs);
  }

  /**
   * Check output coherence
   */
  async checkCoherence(output: string): Promise<CoherenceResult | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.coherence.check(output);
  }

  /**
   * Process input through full neural substrate
   */
  async process(input: string, context?: {
    agentId?: string;
    memoryId?: string;
    checkCoherence?: boolean;
  }): Promise<{
    drift: DriftResult;
    state?: { nearestRegion: string; regionProximity: number };
    coherence?: CoherenceResult;
    stored?: boolean;
  } | null> {
    if (!this.available || !this.substrate) return null;
    return this.substrate.process(input, context);
  }

  /**
   * Get substrate health
   */
  health(): SubstrateHealth | null {
    if (!this.available || !this.substrate) return null;
    return this.substrate.health();
  }

  /**
   * Full consolidation pass
   */
  consolidate(): { memory: { merged: number; forgotten: number; remaining: number } } | null {
    if (!this.available || !this.substrate) return null;
    return this.substrate.consolidate();
  }
}

/**
 * Create neural embedding service
 */
export function createNeuralService(config: NeuralSubstrateConfig = {}): NeuralEmbeddingService {
  return new NeuralEmbeddingService(config);
}

/**
 * Check if neural features are available
 */
export async function isNeuralAvailable(): Promise<boolean> {
  try {
    await import('agentic-flow/embeddings');
    return true;
  } catch {
    return false;
  }
}

/**
 * List available ONNX embedding models
 */
export async function listEmbeddingModels(): Promise<Array<{
  id: string;
  dimension: number;
  size: string;
  quantized: boolean;
  downloaded: boolean;
}>> {
  try {
    const { listAvailableModels } = await import('agentic-flow/embeddings');
    return listAvailableModels();
  } catch {
    // Return default models if agentic-flow not available
    return [
      { id: 'all-MiniLM-L6-v2', dimension: 384, size: '23MB', quantized: false, downloaded: false },
      { id: 'all-mpnet-base-v2', dimension: 768, size: '110MB', quantized: false, downloaded: false },
    ];
  }
}

/**
 * Download embedding model.
 *
 * #1700 item 2: previously this propagated `Cannot find package 'agentic-flow'`
 * when the optional peer wasn't installed, breaking `embeddings init` even
 * though the rest of the embedding pipeline (Xenova/transformers ONNX) does
 * not need agentic-flow. Now we try the agentic-flow path first and fall
 * back to a no-op success when it isn't installed — the model still loads
 * lazily on first `embeddings_generate` call via @xenova/transformers.
 */
export async function downloadEmbeddingModel(
  modelId: string,
  targetDir?: string,
  onProgress?: (progress: { percent: number; bytesDownloaded: number; totalBytes: number }) => void
): Promise<string> {
  try {
    const mod = await import('agentic-flow/embeddings').catch((err) => {
      throw err;
    });
    const downloadFn = (mod as Record<string, unknown>).downloadModel;
    if (typeof downloadFn !== 'function') {
      // agentic-flow is installed but has no downloadModel export (the
      // 2.x line shipped clearEmbeddingCache/computeEmbedding* but not
      // downloadModel; the function lives on a different path or version).
      // Treat as lazy-fetch path — @xenova/transformers will download on
      // first generate(). #1700 item 2 follow-up.
      console.warn('[embeddings] agentic-flow installed but does not expose downloadModel — ' +
        'falling back to lazy fetch via @xenova/transformers on first generate.');
      return targetDir ?? '.models';
    }
    return await (downloadFn as (id: string, dir: string, cb?: typeof onProgress) => Promise<string>)(
      modelId, targetDir ?? '.models', onProgress
    );
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err);
    // Distinguish "package missing" / "subpath unsupported" from real
    // download errors so callers can surface the right hint to users.
    // #1468: Windows + Node strict-ESM raises
    //   `Package subpath './embeddings' is not defined by "exports"`
    // when the bundled agentic-flow's package.json doesn't declare the
    // ./embeddings entry. WSL/Linux is more permissive on the same code,
    // so the bug only surfaces on Windows. Treat both shapes as
    // "agentic-flow neural extras unavailable, fall back to lazy fetch".
    if (
      /Cannot find package 'agentic-flow'|Cannot find module/.test(msg)
      || /Package subpath ['"]\.\/embeddings['"] is not defined/.test(msg)
      || /ERR_PACKAGE_PATH_NOT_EXPORTED/.test(msg)
    ) {
      console.warn('[embeddings] agentic-flow neural extras unavailable — skipping eager model download. ' +
        'Models will be fetched lazily by @xenova/transformers on first generate. ' +
        `Reason: ${msg}`);
      return targetDir ?? '.models';
    }
    throw err;
  }
}

/**
 * Embedding Normalization Utilities
 *
 * Features:
 * - L2 (Euclidean) normalization
 * - L1 (Manhattan) normalization
 * - Min-max normalization
 * - Z-score standardization
 * - Batch normalization
 */

/**
 * Normalization type
 */
export type NormalizationType = 'l2' | 'l1' | 'minmax' | 'zscore' | 'none';

/**
 * Normalization options
 */
export interface NormalizationOptions {
  /** Normalization type (default: 'l2') */
  type?: NormalizationType;
  /** Epsilon for numerical stability (default: 1e-12) */
  epsilon?: number;
  /** In-place modification (default: false) */
  inPlace?: boolean;
}

/**
 * L2 (Euclidean) normalize embedding to unit length
 * Most common for cosine similarity
 *
 * @param embedding - Input embedding vector
 * @param epsilon - Small value to prevent division by zero
 * @returns Normalized embedding with ||v|| = 1
 */
export function l2Normalize(
  embedding: Float32Array | number[],
  epsilon = 1e-12
): Float32Array {
  const result = embedding instanceof Float32Array
    ? new Float32Array(embedding.length)
    : new Float32Array(embedding.length);

  // Calculate L2 norm (Euclidean length)
  let sumSquares = 0;
  for (let i = 0; i < embedding.length; i++) {
    sumSquares += embedding[i] * embedding[i];
  }

  const norm = Math.sqrt(sumSquares);
  const scale = norm > epsilon ? 1 / norm : 0;

  // Normalize
  for (let i = 0; i < embedding.length; i++) {
    result[i] = embedding[i] * scale;
  }

  return result;
}

/**
 * L2 normalize embedding in-place (modifies original array)
 */
export function l2NormalizeInPlace(
  embedding: Float32Array,
  epsilon = 1e-12
): Float32Array {
  let sumSquares = 0;
  for (let i = 0; i < embedding.length; i++) {
    sumSquares += embedding[i] * embedding[i];
  }

  const norm = Math.sqrt(sumSquares);
  const scale = norm > epsilon ? 1 / norm : 0;

  for (let i = 0; i < embedding.length; i++) {
    embedding[i] *= scale;
  }

  return embedding;
}

/**
 * L1 (Manhattan) normalize embedding
 * Sum of absolute values = 1
 */
export function l1Normalize(
  embedding: Float32Array | number[],
  epsilon = 1e-12
): Float32Array {
  const result = new Float32Array(embedding.length);

  // Calculate L1 norm (sum of absolute values)
  let sumAbs = 0;
  for (let i = 0; i < embedding.length; i++) {
    sumAbs += Math.abs(embedding[i]);
  }

  const scale = sumAbs > epsilon ? 1 / sumAbs : 0;

  for (let i = 0; i < embedding.length; i++) {
    result[i] = embedding[i] * scale;
  }

  return result;
}

/**
 * Min-max normalize embedding to [0, 1] range
 */
export function minMaxNormalize(
  embedding: Float32Array | number[],
  epsilon = 1e-12
): Float32Array {
  const result = new Float32Array(embedding.length);

  // Find min and max
  let min = Infinity;
  let max = -Infinity;

  for (let i = 0; i < embedding.length; i++) {
    if (embedding[i] < min) min = embedding[i];
    if (embedding[i] > max) max = embedding[i];
  }

  const range = max - min;
  const scale = range > epsilon ? 1 / range : 0;

  for (let i = 0; i < embedding.length; i++) {
    result[i] = (embedding[i] - min) * scale;
  }

  return result;
}

/**
 * Z-score standardize embedding (mean=0, std=1)
 */
export function zScoreNormalize(
  embedding: Float32Array | number[],
  epsilon = 1e-12
): Float32Array {
  const result = new Float32Array(embedding.length);
  const n = embedding.length;

  // Calculate mean
  let sum = 0;
  for (let i = 0; i < n; i++) {
    sum += embedding[i];
  }
  const mean = sum / n;

  // Calculate standard deviation
  let sumSquaredDiff = 0;
  for (let i = 0; i < n; i++) {
    const diff = embedding[i] - mean;
    sumSquaredDiff += diff * diff;
  }
  const std = Math.sqrt(sumSquaredDiff / n);
  const scale = std > epsilon ? 1 / std : 0;

  // Standardize
  for (let i = 0; i < n; i++) {
    result[i] = (embedding[i] - mean) * scale;
  }

  return result;
}

/**
 * Normalize embedding using specified method
 */
export function normalize(
  embedding: Float32Array | number[],
  options: NormalizationOptions = {}
): Float32Array {
  const { type = 'l2', epsilon = 1e-12, inPlace = false } = options;

  if (type === 'none') {
    return embedding instanceof Float32Array
      ? embedding
      : new Float32Array(embedding);
  }

  if (inPlace && embedding instanceof Float32Array && type === 'l2') {
    return l2NormalizeInPlace(embedding, epsilon);
  }

  switch (type) {
    case 'l2':
      return l2Normalize(embedding, epsilon);
    case 'l1':
      return l1Normalize(embedding, epsilon);
    case 'minmax':
      return minMaxNormalize(embedding, epsilon);
    case 'zscore':
      return zScoreNormalize(embedding, epsilon);
    default:
      return l2Normalize(embedding, epsilon);
  }
}

/**
 * Batch normalize multiple embeddings
 */
export function normalizeBatch(
  embeddings: Array<Float32Array | number[]>,
  options: NormalizationOptions = {}
): Float32Array[] {
  return embeddings.map(emb => normalize(emb, options));
}

/**
 * Calculate L2 norm of embedding
 */
export function l2Norm(embedding: Float32Array | number[]): number {
  let sumSquares = 0;
  for (let i = 0; i < embedding.length; i++) {
    sumSquares += embedding[i] * embedding[i];
  }
  return Math.sqrt(sumSquares);
}

/**
 * Check if embedding is already normalized (L2 norm ≈ 1)
 */
export function isNormalized(
  embedding: Float32Array | number[],
  tolerance = 1e-6
): boolean {
  const norm = l2Norm(embedding);
  return Math.abs(norm - 1) < tolerance;
}

/**
 * Center embeddings by subtracting mean across batch
 * Useful for improving similarity metrics
 */
export function centerEmbeddings(
  embeddings: Array<Float32Array | number[]>
): Float32Array[] {
  if (embeddings.length === 0) return [];

  const dim = embeddings[0].length;
  const n = embeddings.length;

  // Calculate mean for each dimension
  const mean = new Float32Array(dim);
  for (const emb of embeddings) {
    for (let i = 0; i < dim; i++) {
      mean[i] += emb[i];
    }
  }
  for (let i = 0; i < dim; i++) {
    mean[i] /= n;
  }

  // Subtract mean from each embedding
  return embeddings.map(emb => {
    const centered = new Float32Array(dim);
    for (let i = 0; i < dim; i++) {
      centered[i] = emb[i] - mean[i];
    }
    return centered;
  });
}

/**
 * SQLite-backed Persistent Cache for Embeddings (sql.js)
 *
 * Features:
 * - Cross-platform support (pure JavaScript/WASM, no native compilation)
 * - Disk persistence across sessions
 * - LRU eviction with configurable max size
 * - Automatic schema creation
 * - TTL support for cache entries
 * - Lazy initialization (no startup cost if not used)
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync } from 'fs';
import { dirname } from 'path';

// Use 'any' for sql.js types to avoid complex typing issues
// sql.js has its own types but they don't always match perfectly
type SqlJsDatabase = any;
type SqlJsStatic = any;

/**
 * Configuration for persistent cache
 */
export interface PersistentCacheConfig {
  /** Path to SQLite database file */
  dbPath: string;
  /** Maximum number of entries (default: 10000) */
  maxSize?: number;
  /** TTL in milliseconds (default: 7 days) */
  ttlMs?: number;
  /** Enable compression for large embeddings */
  compress?: boolean;
  /** Auto-save interval in ms (default: 30000) */
  autoSaveInterval?: number;
}

/**
 * Cache statistics
 */
export interface PersistentCacheStats {
  size: number;
  maxSize: number;
  hitRate: number;
  hits: number;
  misses: number;
  dbSizeBytes?: number;
}

/**
 * SQLite-backed persistent embedding cache using sql.js (pure JS/WASM)
 */
export class PersistentEmbeddingCache {
  private db: SqlJsDatabase | null = null;
  private SQL: SqlJsStatic | null = null;
  private initialized = false;
  private dirty = false;
  private hits = 0;
  private misses = 0;
  private autoSaveTimer: ReturnType<typeof setInterval> | null = null;

  private readonly dbPath: string;
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly autoSaveInterval: number;

  constructor(config: PersistentCacheConfig) {
    this.dbPath = config.dbPath;
    this.maxSize = config.maxSize ?? 10000;
    this.ttlMs = config.ttlMs ?? 7 * 24 * 60 * 60 * 1000; // 7 days
    this.autoSaveInterval = config.autoSaveInterval ?? 30000; // 30 seconds
  }

  /**
   * Lazily initialize database connection
   */
  private async ensureInitialized(): Promise<void> {
    if (this.initialized) return;

    try {
      // Dynamically import sql.js
      const initSqlJs = (await import('sql.js')).default;

      // Initialize sql.js (loads WASM)
      this.SQL = await initSqlJs();

      // Ensure directory exists
      const dir = dirname(this.dbPath);
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }

      // Load existing database or create new
      if (existsSync(this.dbPath)) {
        const fileBuffer = readFileSync(this.dbPath);
        this.db = new this.SQL.Database(fileBuffer);
      } else {
        this.db = new this.SQL.Database();
      }

      // Create schema
      this.db.run(`
        CREATE TABLE IF NOT EXISTS embeddings (
          key TEXT PRIMARY KEY,
          embedding BLOB NOT NULL,
          dimensions INTEGER NOT NULL,
          created_at INTEGER NOT NULL,
          accessed_at INTEGER NOT NULL,
          access_count INTEGER DEFAULT 1
        )
      `);
      this.db.run('CREATE INDEX IF NOT EXISTS idx_accessed_at ON embeddings(accessed_at)');
      this.db.run('CREATE INDEX IF NOT EXISTS idx_created_at ON embeddings(created_at)');

      // Clean expired entries on startup
      this.cleanExpired();

      // Save after initialization to persist schema
      this.saveToFile();

      // Start auto-save timer
      this.startAutoSave();

      this.initialized = true;
    } catch (error) {
      // If sql.js not available, fall back gracefully
      console.warn('[persistent-cache] sql.js not available, cache disabled:',
        error instanceof Error ? error.message : error);
      this.initialized = true; // Mark as initialized to prevent retry
    }
  }

  /**
   * Start auto-save timer
   */
  private startAutoSave(): void {
    if (this.autoSaveTimer) return;

    this.autoSaveTimer = setInterval(() => {
      if (this.dirty && this.db) {
        this.saveToFile();
      }
    }, this.autoSaveInterval);
  }

  /**
   * Stop auto-save timer
   */
  private stopAutoSave(): void {
    if (this.autoSaveTimer) {
      clearInterval(this.autoSaveTimer);
      this.autoSaveTimer = null;
    }
  }

  /**
   * Save database to file
   */
  private saveToFile(): void {
    if (!this.db) return;

    try {
      const data = this.db.export();
      const buffer = Buffer.from(data);
      writeFileSync(this.dbPath, buffer);
      this.dirty = false;
    } catch (error) {
      console.error('[persistent-cache] Save error:', error);
    }
  }

  /**
   * Generate cache key from text
   */
  private hashKey(text: string): string {
    // FNV-1a hash for fast, deterministic key generation
    let hash = 0x811c9dc5;
    for (let i = 0; i < text.length; i++) {
      hash ^= text.charCodeAt(i);
      hash = (hash * 0x01000193) >>> 0;
    }
    return `emb_${hash.toString(16)}_${text.length}`;
  }

  /**
   * Serialize Float32Array to Uint8Array for sql.js
   */
  private serializeEmbedding(embedding: Float32Array): Uint8Array {
    return new Uint8Array(embedding.buffer, embedding.byteOffset, embedding.byteLength);
  }

  /**
   * Deserialize Uint8Array to Float32Array
   */
  private deserializeEmbedding(data: Uint8Array, dimensions: number): Float32Array {
    const buffer = new ArrayBuffer(data.length);
    const view = new Uint8Array(buffer);
    view.set(data);
    return new Float32Array(buffer);
  }

  /**
   * Get embedding from cache
   */
  async get(text: string): Promise<Float32Array | null> {
    await this.ensureInitialized();
    if (!this.db) {
      this.misses++;
      return null;
    }

    const key = this.hashKey(text);
    const now = Date.now();

    try {
      const stmt = this.db.prepare(`
        SELECT embedding, dimensions, created_at
        FROM embeddings
        WHERE key = ?
      `);
      stmt.bind([key]);

      if (!stmt.step()) {
        stmt.free();
        this.misses++;
        return null;
      }

      const row = stmt.getAsObject() as {
        embedding: Uint8Array;
        dimensions: number;
        created_at: number;
      };
      stmt.free();

      // Check TTL
      if (now - row.created_at > this.ttlMs) {
        this.db.run('DELETE FROM embeddings WHERE key = ?', [key]);
        this.dirty = true;
        this.misses++;
        return null;
      }

      // Update access time and count
      this.db.run(`
        UPDATE embeddings
        SET accessed_at = ?, access_count = access_count + 1
        WHERE key = ?
      `, [now, key]);
      this.dirty = true;

      this.hits++;
      return this.deserializeEmbedding(row.embedding, row.dimensions);
    } catch (error) {
      console.error('[persistent-cache] Get error:', error);
      this.misses++;
      return null;
    }
  }

  /**
   * Store embedding in cache
   */
  async set(text: string, embedding: Float32Array): Promise<void> {
    await this.ensureInitialized();
    if (!this.db) return;

    const key = this.hashKey(text);
    const now = Date.now();
    const data = this.serializeEmbedding(embedding);

    try {
      // Upsert entry using INSERT OR REPLACE
      this.db.run(`
        INSERT OR REPLACE INTO embeddings
        (key, embedding, dimensions, created_at, accessed_at, access_count)
        VALUES (?, ?, ?, ?, ?,
          COALESCE((SELECT access_count + 1 FROM embeddings WHERE key = ?), 1)
        )
      `, [key, data, embedding.length, now, now, key]);
      this.dirty = true;

      // Check size and evict if needed
      await this.evictIfNeeded();
    } catch (error) {
      console.error('[persistent-cache] Set error:', error);
    }
  }

  /**
   * Evict oldest entries if cache exceeds max size
   */
  private async evictIfNeeded(): Promise<void> {
    if (!this.db) return;

    const result = this.db.exec('SELECT COUNT(*) as count FROM embeddings');
    const count = result[0]?.values[0]?.[0] as number ?? 0;

    if (count > this.maxSize) {
      const toDelete = count - this.maxSize + Math.floor(this.maxSize * 0.1); // Delete 10% extra
      this.db.run(`
        DELETE FROM embeddings
        WHERE key IN (
          SELECT key FROM embeddings
          ORDER BY accessed_at ASC
          LIMIT ?
        )
      `, [toDelete]);
      this.dirty = true;
    }
  }

  /**
   * Clean expired entries
   */
  private cleanExpired(): void {
    if (!this.db) return;

    const cutoff = Date.now() - this.ttlMs;
    this.db.run('DELETE FROM embeddings WHERE created_at < ?', [cutoff]);
    this.dirty = true;
  }

  /**
   * Get cache statistics
   */
  async getStats(): Promise<PersistentCacheStats> {
    await this.ensureInitialized();

    const total = this.hits + this.misses;
    const stats: PersistentCacheStats = {
      size: 0,
      maxSize: this.maxSize,
      hitRate: total > 0 ? this.hits / total : 0,
      hits: this.hits,
      misses: this.misses,
    };

    if (this.db) {
      const result = this.db.exec('SELECT COUNT(*) as count FROM embeddings');
      stats.size = result[0]?.values[0]?.[0] as number ?? 0;

      // Get file size if exists
      if (existsSync(this.dbPath)) {
        try {
          const buffer = readFileSync(this.dbPath);
          stats.dbSizeBytes = buffer.length;
        } catch {
          // Ignore
        }
      }
    }

    return stats;
  }

  /**
   * Clear all cached entries
   */
  async clear(): Promise<void> {
    await this.ensureInitialized();
    if (!this.db) return;

    this.db.run('DELETE FROM embeddings');
    this.dirty = true;
    this.hits = 0;
    this.misses = 0;
    this.saveToFile();
  }

  /**
   * Force save to disk
   */
  async flush(): Promise<void> {
    await this.ensureInitialized();
    if (this.db && this.dirty) {
      this.saveToFile();
    }
  }

  /**
   * Close database connection
   */
  async close(): Promise<void> {
    this.stopAutoSave();

    if (this.db) {
      // Save before closing
      if (this.dirty) {
        this.saveToFile();
      }
      this.db.close();
      this.db = null;
      this.SQL = null;
      this.initialized = false;
    }
  }
}

/**
 * Check if persistent cache is available (sql.js installed)
 */
export async function isPersistentCacheAvailable(): Promise<boolean> {
  try {
    const initSqlJs = (await import('sql.js')).default;
    await initSqlJs();
    return true;
  } catch {
    return false;
  }
}

/**
 * RVF Embedding Cache - Pure TypeScript Binary File Cache
 *
 * Replaces the sql.js-based PersistentEmbeddingCache with a lightweight
 * pure-TS binary file format. No native dependencies required.
 *
 * Features:
 * - Map-based in-memory cache with periodic flush to binary file
 * - LRU eviction tracked via access timestamps
 * - TTL support for cache entries
 * - Deterministic FNV-1a text hashing for keys
 * - Binary format: RVEC magic + entry records
 *
 * Binary entry format:
 *   [4-byte key-hash][4-byte dims][dims*4 bytes float32][8-byte timestamp][8-byte access-count]
 *
 * @module @claude-flow/embeddings
 */

import { existsSync, mkdirSync, readFileSync, writeFileSync, renameSync } from 'fs';
import { dirname } from 'path';

/** Validate a file path is safe */
function validatePath(p: string): void {
  if (p.includes('\0')) throw new Error('Cache path contains null bytes');
}

// ============================================================================
// Configuration
// ============================================================================

/**
 * Configuration for RVF embedding cache
 */
export interface RvfEmbeddingCacheConfig {
  /** Path to the binary cache file */
  cachePath: string;
  /** Maximum number of entries (default: 10000) */
  maxSize?: number;
  /** TTL in milliseconds (default: 7 days) */
  ttlMs?: number;
  /** Embedding dimensions (used for validation) */
  dimensions?: number;
}

// ============================================================================
// Cache Entry
// ============================================================================

interface CacheEntry {
  embedding: Float32Array;
  createdAt: number;
  accessedAt: number;
  accessCount: number;
}

// ============================================================================
// Constants
// ============================================================================

/** Binary file magic bytes: "RVEC" */
const MAGIC = new Uint8Array([0x52, 0x56, 0x45, 0x43]); // R V E C

/** Default TTL: 7 days in milliseconds */
const DEFAULT_TTL_MS = 7 * 24 * 60 * 60 * 1000;

/** Default max entries */
const DEFAULT_MAX_SIZE = 10000;

/** Auto-flush interval: 30 seconds */
const AUTO_FLUSH_INTERVAL_MS = 30000;

/** FNV-1a offset basis (32-bit) */
const FNV_OFFSET_BASIS = 0x811c9dc5;

/** FNV-1a prime (32-bit) */
const FNV_PRIME = 0x01000193;

// ============================================================================
// RVF Embedding Cache
// ============================================================================

/**
 * Pure-TS binary file embedding cache with LRU eviction and TTL support.
 *
 * Stores embeddings as raw Float32Array bytes keyed by FNV-1a text hashes.
 * Uses an in-memory Map with periodic flush to a compact binary file.
 */
export class RvfEmbeddingCache {
  private readonly cachePath: string;
  private readonly maxSize: number;
  private readonly ttlMs: number;
  private readonly dimensions: number | undefined;

  private entries: Map<number, CacheEntry> = new Map();
  private textToHash: Map<string, number> = new Map();
  private dirty = false;
  private flushTimer: ReturnType<typeof setInterval> | null = null;
  private initialized = false;

  constructor(config: RvfEmbeddingCacheConfig) {
    this.cachePath = config.cachePath;
    this.maxSize = config.maxSize ?? DEFAULT_MAX_SIZE;
    this.ttlMs = config.ttlMs ?? DEFAULT_TTL_MS;
    this.dimensions = config.dimensions;
    validatePath(this.cachePath);
  }

  // --------------------------------------------------------------------------
  // Initialization
  // --------------------------------------------------------------------------

  /**
   * Lazily initialize the cache: load from disk if file exists, start auto-flush.
   */
  private async ensureInitialized(): Promise<void> {
    if (this.initialized) return;

    // Ensure parent directory exists
    const dir = dirname(this.cachePath);
    if (!existsSync(dir)) {
      mkdirSync(dir, { recursive: true });
    }

    // Load existing cache file
    if (existsSync(this.cachePath)) {
      this.loadFromFile();
    }

    // Clean expired entries on startup
    this.cleanExpired();

    // Start auto-flush timer
    this.startAutoFlush();

    this.initialized = true;
  }

  // --------------------------------------------------------------------------
  // Public API (matches PersistentEmbeddingCache)
  // --------------------------------------------------------------------------

  /**
   * Get an embedding from the cache by text.
   * Returns null if not found or expired.
   */
  async get(text: string): Promise<Float32Array | null> {
    await this.ensureInitialized();

    const hash = this.hashText(text);
    const entry = this.entries.get(hash);

    if (!entry) {
      return null;
    }

    // Check TTL
    const now = Date.now();
    if (now - entry.createdAt > this.ttlMs) {
      this.entries.delete(hash);
      this.textToHash.delete(text);
      this.dirty = true;
      return null;
    }

    // Update LRU tracking
    entry.accessedAt = now;
    entry.accessCount++;
    this.dirty = true;

    return entry.embedding;
  }

  /**
   * Store an embedding in the cache.
   * Triggers LRU eviction if the cache exceeds maxSize.
   */
  async set(text: string, embedding: Float32Array): Promise<void> {
    await this.ensureInitialized();

    // Validate dimensions if configured
    if (this.dimensions !== undefined && embedding.length !== this.dimensions) {
      throw new Error(
        `Dimension mismatch: expected ${this.dimensions}, got ${embedding.length}`
      );
    }

    const hash = this.hashText(text);
    const now = Date.now();

    // Copy the embedding to avoid external mutation
    const copy = new Float32Array(embedding.length);
    copy.set(embedding);

    const existing = this.entries.get(hash);
    if (existing) {
      existing.embedding = copy;
      existing.accessedAt = now;
      existing.accessCount++;
    } else {
      this.entries.set(hash, {
        embedding: copy,
        createdAt: now,
        accessedAt: now,
        accessCount: 1,
      });
      this.textToHash.set(text, hash);
    }

    this.dirty = true;

    // Evict if over capacity
    this.evictIfNeeded();
  }

  /**
   * Check whether the cache contains an embedding for the given text.
   */
  async has(text: string): Promise<boolean> {
    await this.ensureInitialized();

    const hash = this.hashText(text);
    const entry = this.entries.get(hash);

    if (!entry) return false;

    // Check TTL
    if (Date.now() - entry.createdAt > this.ttlMs) {
      this.entries.delete(hash);
      this.textToHash.delete(text);
      this.dirty = true;
      return false;
    }

    return true;
  }

  /**
   * Delete a specific entry from the cache.
   * Returns true if the entry existed and was deleted.
   */
  async delete(text: string): Promise<boolean> {
    await this.ensureInitialized();

    const hash = this.hashText(text);
    const existed = this.entries.delete(hash);
    this.textToHash.delete(text);

    if (existed) {
      this.dirty = true;
    }

    return existed;
  }

  /**
   * Clear all entries from the cache and persist the empty state.
   */
  async clear(): Promise<void> {
    await this.ensureInitialized();

    this.entries.clear();
    this.textToHash.clear();
    this.dirty = true;
    this.flushToFile();
  }

  /**
   * Return the number of entries currently in the cache.
   */
  async size(): Promise<number> {
    await this.ensureInitialized();
    return this.entries.size;
  }

  /**
   * Flush pending changes to disk and stop the auto-flush timer.
   */
  async close(): Promise<void> {
    this.stopAutoFlush();

    if (this.dirty) {
      this.flushToFile();
    }

    this.entries.clear();
    this.textToHash.clear();
    this.initialized = false;
  }

  // --------------------------------------------------------------------------
  // Hashing
  // --------------------------------------------------------------------------

  /**
   * FNV-1a 32-bit hash of the input text.
   * Deterministic: same input always produces the same hash.
   */
  private hashText(text: string): number {
    let hash = FNV_OFFSET_BASIS;
    for (let i = 0; i < text.length; i++) {
      hash ^= text.charCodeAt(i);
      hash = Math.imul(hash, FNV_PRIME) >>> 0;
    }
    return hash;
  }

  // --------------------------------------------------------------------------
  // LRU Eviction
  // --------------------------------------------------------------------------

  /**
   * If the cache exceeds maxSize, evict the least-recently-accessed entries
   * until we are back at 90% capacity.
   */
  private evictIfNeeded(): void {
    if (this.entries.size <= this.maxSize) return;

    const targetSize = Math.floor(this.maxSize * 0.9);
    const toEvict = this.entries.size - targetSize;

    // Sort entries by accessedAt ascending (oldest first)
    const sorted = [...this.entries.entries()].sort(
      (a, b) => a[1].accessedAt - b[1].accessedAt
    );

    // Build reverse map for O(1) lookup (hash → text)
    const hashToText = new Map<number, string>();
    for (const [text, hash] of this.textToHash) {
      hashToText.set(hash, text);
    }

    for (let i = 0; i < toEvict && i < sorted.length; i++) {
      const [hash] = sorted[i];
      this.entries.delete(hash);
      const text = hashToText.get(hash);
      if (text !== undefined) this.textToHash.delete(text);
    }

    this.dirty = true;
  }

  // --------------------------------------------------------------------------
  // TTL Cleanup
  // --------------------------------------------------------------------------

  /**
   * Remove all entries whose createdAt timestamp is older than TTL.
   */
  private cleanExpired(): void {
    const cutoff = Date.now() - this.ttlMs;
    const toDelete: number[] = [];

    for (const [hash, entry] of this.entries) {
      if (entry.createdAt < cutoff) {
        toDelete.push(hash);
      }
    }

    // Build reverse map for O(1) lookup
    const hashToText = new Map<number, string>();
    for (const [text, h] of this.textToHash) {
      hashToText.set(h, text);
    }

    for (const hash of toDelete) {
      this.entries.delete(hash);
      const text = hashToText.get(hash);
      if (text !== undefined) this.textToHash.delete(text);
    }

    if (toDelete.length > 0) {
      this.dirty = true;
    }
  }

  // --------------------------------------------------------------------------
  // Auto-Flush Timer
  // --------------------------------------------------------------------------

  private startAutoFlush(): void {
    if (this.flushTimer) return;

    this.flushTimer = setInterval(() => {
      if (this.dirty) {
        this.flushToFile();
      }
    }, AUTO_FLUSH_INTERVAL_MS);
    if (this.flushTimer.unref) this.flushTimer.unref();
  }

  private stopAutoFlush(): void {
    if (this.flushTimer) {
      clearInterval(this.flushTimer);
      this.flushTimer = null;
    }
  }

  // --------------------------------------------------------------------------
  // Binary Serialization
  // --------------------------------------------------------------------------

  /**
   * Write all entries to the binary cache file.
   *
   * Format:
   *   [4-byte magic "RVEC"]
   *   For each entry:
   *     [4-byte key-hash (uint32)]
   *     [4-byte dims (uint32)]
   *     [dims * 4 bytes float32 data]
   *     [8-byte createdAt (float64, used as timestamp)]
   *     [8-byte accessCount (float64)]
   */
  private flushToFile(): void {
    try {
      // Version 2 format: magic(4) + version(4) + entries...
      // Entry: hash(4) + dims(4) + embedding(dims*4) + createdAt(8) + accessedAt(8) + accessCount(8)
      let totalSize = MAGIC.length + 4; // magic + version uint32
      for (const [, entry] of this.entries) {
        totalSize += 4 + 4 + entry.embedding.length * 4 + 8 + 8 + 8;
      }

      const buffer = new ArrayBuffer(totalSize);
      const view = new DataView(buffer);
      const bytes = new Uint8Array(buffer);
      let offset = 0;

      // Write magic
      bytes.set(MAGIC, 0);
      offset += MAGIC.length;

      // Write format version
      view.setUint32(offset, 2, true);
      offset += 4;

      // Write entries
      for (const [hash, entry] of this.entries) {
        // Key hash (uint32, little-endian)
        view.setUint32(offset, hash, true);
        offset += 4;

        // Dimensions (uint32, little-endian)
        view.setUint32(offset, entry.embedding.length, true);
        offset += 4;

        // Embedding data (float32 array, little-endian)
        for (let i = 0; i < entry.embedding.length; i++) {
          view.setFloat32(offset, entry.embedding[i], true);
          offset += 4;
        }

        // createdAt as float64 (little-endian) - v2: separate from accessedAt
        view.setFloat64(offset, entry.createdAt, true);
        offset += 8;

        // accessedAt as float64 (little-endian)
        view.setFloat64(offset, entry.accessedAt, true);
        offset += 8;

        // Access count as float64 (little-endian)
        view.setFloat64(offset, entry.accessCount, true);
        offset += 8;
      }

      // Ensure parent directory exists
      const dir = dirname(this.cachePath);
      if (!existsSync(dir)) {
        mkdirSync(dir, { recursive: true });
      }

      const tmpSuffix = Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
      const tmpPath = this.cachePath + '.tmp.' + tmpSuffix;
      writeFileSync(tmpPath, Buffer.from(buffer));
      renameSync(tmpPath, this.cachePath);
      this.dirty = false;
    } catch (error) {
      console.error(
        '[rvf-embedding-cache] Flush error:',
        error instanceof Error ? error.message : error
      );
    }
  }

  /**
   * Load entries from the binary cache file.
   */
  private loadFromFile(): void {
    try {
      const fileBuffer = readFileSync(this.cachePath);
      if (fileBuffer.length < MAGIC.length) return;

      const buffer = fileBuffer.buffer.slice(
        fileBuffer.byteOffset,
        fileBuffer.byteOffset + fileBuffer.byteLength
      );
      const view = new DataView(buffer);
      const bytes = new Uint8Array(buffer);
      let offset = 0;

      // Verify magic
      for (let i = 0; i < MAGIC.length; i++) {
        if (bytes[offset + i] !== MAGIC[i]) {
          console.warn('[rvf-embedding-cache] Invalid magic bytes, skipping load');
          return;
        }
      }
      offset += MAGIC.length;

      // Check for version header (v2+)
      let formatVersion = 1;
      if (offset + 4 <= buffer.byteLength) {
        const possibleVersion = view.getUint32(offset, true);
        if (possibleVersion === 2) {
          formatVersion = possibleVersion;
          offset += 4;
        }
      }

      // Read entries
      while (offset + 8 <= buffer.byteLength) {
        // Need at least 4 (hash) + 4 (dims) = 8 bytes for the header
        const hash = view.getUint32(offset, true);
        offset += 4;

        const dims = view.getUint32(offset, true);
        offset += 4;

        const entryDataSize = formatVersion === 2
          ? dims * 4 + 8 + 8 + 8   // v2: embedding + createdAt + accessedAt + accessCount
          : dims * 4 + 8 + 8;       // v1: embedding + accessedAt + accessCount
        if (offset + entryDataSize > buffer.byteLength) {
          console.warn('[rvf-embedding-cache] Truncated entry, stopping load');
          break;
        }

        // Read embedding
        const embedding = new Float32Array(dims);
        for (let i = 0; i < dims; i++) {
          embedding[i] = view.getFloat32(offset, true);
          offset += 4;
        }

        let createdAt: number;
        let accessedAt: number;
        let accessCount: number;

        if (formatVersion >= 2) {
          createdAt = view.getFloat64(offset, true);
          offset += 8;
          accessedAt = view.getFloat64(offset, true);
          offset += 8;
          accessCount = view.getFloat64(offset, true);
          offset += 8;
        } else {
          // v1: only accessedAt was stored, use it as createdAt too
          accessedAt = view.getFloat64(offset, true);
          offset += 8;
          accessCount = view.getFloat64(offset, true);
          offset += 8;
          createdAt = accessedAt;
        }

        this.entries.set(hash, {
          embedding,
          createdAt,
          accessedAt,
          accessCount,
        });
      }
    } catch (error) {
      console.warn(
        '[rvf-embedding-cache] Load error:',
        error instanceof Error ? error.message : error
      );
    }
  }
}

/**
 * RVF Embedding Service - Lightweight Hash-Based Embeddings
 *
 * Provides deterministic, sub-millisecond embedding generation using
 * FNV-1a hash-based vectors. No neural model or external API required.
 *
 * Features:
 * - Deterministic: same input always produces the same embedding
 * - FNV-1a hash seeding with multi-round mixing
 * - L2-normalized output vectors
 * - Sub-millisecond generation (<0.1ms typical)
 * - RvfEmbeddingCache for binary file persistence
 * - Zero external dependencies
 *
 * Use cases:
 * - Fast similarity search where relative distances matter more than semantics
 * - Development and testing without API keys
 * - Offline environments without neural model access
 * - Bootstrapping before heavier providers are available
 *
 * @module @claude-flow/embeddings
 */

import { EventEmitter } from 'events';
import type {
  EmbeddingProvider,
  EmbeddingResult,
  BatchEmbeddingResult,
  IEmbeddingService,
  EmbeddingEvent,
  EmbeddingEventListener,
  NormalizationType,
  RvfEmbeddingConfig,
} from './types.js';
import { normalize } from './normalization.js';
import { RvfEmbeddingCache } from './rvf-embedding-cache.js';

// ============================================================================
// Constants
// ============================================================================

/** FNV-1a offset basis (32-bit) */
const FNV_OFFSET_BASIS = 0x811c9dc5;

/** FNV-1a prime (32-bit) */
const FNV_PRIME = 0x01000193;

/** Default embedding dimensions */
const DEFAULT_DIMENSIONS = 384;

/** Default in-memory LRU cache size */
const DEFAULT_CACHE_SIZE = 1000;

// ============================================================================
// LRU Cache (lightweight in-memory)
// ============================================================================

class LRUCache<K, V> {
  private cache: Map<K, V> = new Map();
  private hits = 0;
  private misses = 0;

  constructor(private readonly maxSize: number) {}

  get(key: K): V | undefined {
    const value = this.cache.get(key);
    if (value !== undefined) {
      // Move to end (most recently used)
      this.cache.delete(key);
      this.cache.set(key, value);
      this.hits++;
      return value;
    }
    this.misses++;
    return undefined;
  }

  set(key: K, value: V): void {
    if (this.cache.has(key)) {
      this.cache.delete(key);
    } else if (this.cache.size >= this.maxSize) {
      const firstKey = this.cache.keys().next().value;
      if (firstKey !== undefined) {
        this.cache.delete(firstKey);
      }
    }
    this.cache.set(key, value);
  }

  clear(): void {
    this.cache.clear();
    this.hits = 0;
    this.misses = 0;
  }

  get size(): number {
    return this.cache.size;
  }

  get hitRate(): number {
    const total = this.hits + this.misses;
    return total > 0 ? this.hits / total : 0;
  }

  getStats() {
    return {
      size: this.cache.size,
      maxSize: this.maxSize,
      hits: this.hits,
      misses: this.misses,
      hitRate: this.hitRate,
    };
  }
}

// ============================================================================
// RVF Embedding Service
// ============================================================================

/**
 * Lightweight hash-based embedding service.
 *
 * Generates deterministic embeddings from text using FNV-1a hashing
 * with multi-round mixing and L2 normalization. The output is a unit
 * vector in R^n where n = configured dimensions (default 384).
 *
 * Extends EventEmitter and implements IEmbeddingService for drop-in
 * compatibility with other providers.
 */
export class RvfEmbeddingService extends EventEmitter implements IEmbeddingService {
  readonly provider: EmbeddingProvider = 'rvf';

  private readonly dimensions: number;
  private readonly cache: LRUCache<string, Float32Array>;
  private readonly normalizationType: NormalizationType;
  private readonly embeddingListeners: Set<EmbeddingEventListener> = new Set();
  private persistentCache: RvfEmbeddingCache | null = null;

  constructor(config: RvfEmbeddingConfig) {
    super();
    this.dimensions = config.dimensions ?? DEFAULT_DIMENSIONS;
    if (this.dimensions <= 0 || !Number.isInteger(this.dimensions)) {
      throw new Error(`Invalid dimensions: ${this.dimensions}. Must be a positive integer.`);
    }
    this.cache = new LRUCache(config.cacheSize ?? DEFAULT_CACHE_SIZE);
    this.normalizationType = config.normalization ?? 'none';

    // Initialize persistent RVF cache if a path is provided
    if (config.cachePath) {
      this.persistentCache = new RvfEmbeddingCache({
        cachePath: config.cachePath,
        maxSize: config.cacheSize ?? 10000,
        dimensions: this.dimensions,
      });
    }
  }

  // --------------------------------------------------------------------------
  // IEmbeddingService Implementation
  // --------------------------------------------------------------------------

  /**
   * Generate an embedding for a single text string.
   */
  async embed(text: string): Promise<EmbeddingResult> {
    if (typeof text !== 'string') {
      throw new Error('embed() expects a string argument');
    }

    // Check in-memory cache
    const cached = this.cache.get(text);
    if (cached) {
      this.emitEvent({ type: 'cache_hit', text });
      return { embedding: cached, latencyMs: 0, cached: true };
    }

    // Check persistent cache
    if (this.persistentCache) {
      const persisted = await this.persistentCache.get(text);
      if (persisted) {
        this.cache.set(text, persisted);
        this.emitEvent({ type: 'cache_hit', text });
        return { embedding: persisted, latencyMs: 0, cached: true, persistentCached: true };
      }
    }

    this.emitEvent({ type: 'embed_start', text });
    const startTime = performance.now();

    // Generate deterministic embedding
    const embedding = this.generateHashEmbedding(text);

    // Apply optional normalization (hash embeddings are already L2-normalized,
    // but the user may want a different normalization)
    const normalized = this.applyNormalization(embedding);

    // Store in caches
    this.cache.set(text, normalized);
    if (this.persistentCache) {
      await this.persistentCache.set(text, normalized);
    }

    const latencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'embed_complete', text, latencyMs });

    return { embedding: normalized, latencyMs };
  }

  /**
   * Generate embeddings for multiple text strings.
   */
  async embedBatch(texts: string[]): Promise<BatchEmbeddingResult> {
    if (!Array.isArray(texts)) {
      throw new Error('embedBatch() expects an array of strings');
    }

    this.emitEvent({ type: 'batch_start', count: texts.length });
    const startTime = performance.now();

    const embeddings: Float32Array[] = [];
    let cacheHits = 0;

    for (const text of texts) {
      const cached = this.cache.get(text);
      if (cached) {
        embeddings.push(cached);
        cacheHits++;
        this.emitEvent({ type: 'cache_hit', text });
        continue;
      }

      // Check persistent cache
      if (this.persistentCache) {
        const persisted = await this.persistentCache.get(text);
        if (persisted) {
          this.cache.set(text, persisted);
          embeddings.push(persisted);
          cacheHits++;
          this.emitEvent({ type: 'cache_hit', text });
          continue;
        }
      }

      const embedding = this.generateHashEmbedding(text);
      const normalized = this.applyNormalization(embedding);
      this.cache.set(text, normalized);

      if (this.persistentCache) {
        await this.persistentCache.set(text, normalized);
      }

      embeddings.push(normalized);
    }

    const totalLatencyMs = performance.now() - startTime;
    this.emitEvent({ type: 'batch_complete', count: texts.length, latencyMs: totalLatencyMs });

    return {
      embeddings,
      totalLatencyMs,
      avgLatencyMs: totalLatencyMs / texts.length,
      cacheStats: {
        hits: cacheHits,
        misses: texts.length - cacheHits,
      },
    };
  }

  clearCache(): void {
    const size = this.cache.size;
    this.cache.clear();
    this.emitEvent({ type: 'cache_eviction', size });
  }

  getCacheStats() {
    const stats = this.cache.getStats();
    return {
      size: stats.size,
      maxSize: stats.maxSize,
      hitRate: stats.hitRate,
    };
  }

  async shutdown(): Promise<void> {
    this.clearCache();
    this.embeddingListeners.clear();
    if (this.persistentCache) {
      await this.persistentCache.close();
    }
  }

  // --------------------------------------------------------------------------
  // Event System
  // --------------------------------------------------------------------------

  addEventListener(listener: EmbeddingEventListener): void {
    this.embeddingListeners.add(listener);
  }

  removeEventListener(listener: EmbeddingEventListener): void {
    this.embeddingListeners.delete(listener);
  }

  private emitEvent(event: EmbeddingEvent): void {
    for (const listener of this.embeddingListeners) {
      try {
        listener(event);
      } catch (error) {
        console.error('Error in embedding event listener:', error);
      }
    }
    this.emit(event.type, event);
  }

  // --------------------------------------------------------------------------
  // Hash Embedding Generation
  // --------------------------------------------------------------------------

  /**
   * Generate a deterministic embedding from text using FNV-1a hashing.
   *
   * Algorithm:
   * 1. Compute a base FNV-1a hash of the full text.
   * 2. For each dimension, derive a unique seed by mixing the base hash
   *    with the dimension index using the golden ratio constant.
   * 3. Apply a sine-based pseudo-random transform to spread values.
   * 4. L2-normalize the result to produce a unit vector.
   *
   * This is deterministic: the same text always yields the same vector.
   */
  private generateHashEmbedding(text: string): Float32Array {
    const embedding = new Float32Array(this.dimensions);

    // Compute base FNV-1a hash of the full text
    let baseHash = FNV_OFFSET_BASIS;
    for (let i = 0; i < text.length; i++) {
      baseHash ^= text.charCodeAt(i);
      baseHash = Math.imul(baseHash, FNV_PRIME) >>> 0;
    }

    // Generate each dimension from a mixed seed
    for (let i = 0; i < this.dimensions; i++) {
      // Mix dimension index with the base hash using golden ratio constant
      const seed = (baseHash + Math.imul(i, 0x9E3779B9)) >>> 0;
      // Use sine for pseudo-random distribution in [-1, 1] range
      const x = Math.sin(seed) * 43758.5453;
      embedding[i] = x - Math.floor(x); // fractional part in [0, 1)
      // Shift to [-0.5, 0.5) for zero-centered distribution
      embedding[i] -= 0.5;
    }

    // L2 normalize to unit vector
    let norm = 0;
    for (let i = 0; i < this.dimensions; i++) {
      norm += embedding[i] * embedding[i];
    }
    norm = Math.sqrt(norm);

    if (norm > 0) {
      for (let i = 0; i < this.dimensions; i++) {
        embedding[i] /= norm;
      }
    }

    return embedding;
  }

  /**
   * Apply user-configured normalization if set.
   */
  private applyNormalization(embedding: Float32Array): Float32Array {
    if (this.normalizationType === 'none') {
      return embedding;
    }
    return normalize(embedding, { type: this.normalizationType });
  }
}

/**
 * Provider-agnostic transformers loader.
 *
 * ADR-094: prefer the maintained `@huggingface/transformers` (which
 * pulls in `protobufjs >=7.5.5` and clears the critical RCE CVE
 * chain), fall back to the legacy `@xenova/transformers` for
 * backwards compatibility with consumers who haven't installed the
 * new package yet.
 *
 * Both packages export the same `pipeline()` function with compatible
 * signatures for our usage (`pipeline('feature-extraction', modelId)`),
 * so callers can use the returned function transparently. The `source`
 * field is reported through `embeddings_status.ruvectorStatus` so
 * users can see which package satisfied the runtime.
 */

export type PipelineFn = (
  task: string,
  model?: string,
  options?: Record<string, unknown>,
) => Promise<unknown>;

export interface TransformersHandle {
  pipeline: PipelineFn;
  source: '@huggingface/transformers' | '@xenova/transformers';
  version?: string;
}

let cached: TransformersHandle | null = null;
let cacheChecked = false;

/**
 * Load a working transformers pipeline. Returns null if neither
 * package is installed. Caches the first successful resolution so
 * subsequent calls don't re-import.
 */
export async function loadTransformersPipeline(): Promise<TransformersHandle | null> {
  if (cacheChecked) return cached;
  cacheChecked = true;

  // Use indirect import paths through string variables so TypeScript
  // doesn't try to resolve module types at compile time. Both packages
  // are runtime-optional; types aren't needed for the typed PipelineFn
  // signature we expose.
  const tryLoad = async (specifier: string): Promise<Record<string, unknown> | null> => {
    try {
      // Webpack/tsc can't statically resolve the specifier when it's a
      // variable, which is intentional here — we want runtime resolution
      // that gracefully fails if the package isn't installed.
      const mod = await import(/* @vite-ignore */ specifier);
      return mod as Record<string, unknown>;
    } catch {
      return null;
    }
  };

  // Prefer the maintained successor.
  const hf = await tryLoad('@huggingface/transformers');
  if (hf && typeof hf.pipeline === 'function') {
    cached = {
      pipeline: hf.pipeline as PipelineFn,
      source: '@huggingface/transformers',
      version: typeof hf.version === 'string' ? hf.version : undefined,
    };
    return cached;
  }

  // Fall back to the legacy package so existing installs keep working.
  const xen = await tryLoad('@xenova/transformers');
  if (xen && typeof xen.pipeline === 'function') {
    cached = {
      pipeline: xen.pipeline as PipelineFn,
      source: '@xenova/transformers',
      version: typeof xen.version === 'string' ? xen.version : undefined,
    };
    return cached;
  }

  return null;
}

/**
 * Synchronous probe — returns whether either package was loaded
 * during a previous call to `loadTransformersPipeline()`. For status
 * tools that don't want to trigger a fresh import.
 */
export function getCachedTransformersSource(): TransformersHandle | null {
  return cached;
}

/**
 * V3 Embedding Service Types
 *
 * Type definitions for embedding service aligned with agentic-flow@alpha:
 * - OpenAI provider
 * - Transformers.js provider
 * - Mock provider
 *
 * Performance Targets:
 * - Single embedding: <100ms (API), <50ms (local)
 * - Batch embedding: <500ms for 10 items
 * - Cache hit: <1ms
 */

// ============================================================================
// Provider Types
// ============================================================================

/**
 * Supported embedding providers
 */
export type EmbeddingProvider = 'openai' | 'transformers' | 'mock' | 'agentic-flow' | 'rvf';

/**
 * Normalization type for embeddings
 */
export type NormalizationType = 'l2' | 'l1' | 'minmax' | 'zscore' | 'none';

/**
 * Persistent cache configuration
 */
export interface PersistentCacheConfig {
  /** Enable persistent disk cache (requires better-sqlite3) */
  enabled: boolean;
  /** Path to SQLite database file (default: .cache/embeddings.db) */
  dbPath?: string;
  /** Maximum entries in persistent cache (default: 10000) */
  maxSize?: number;
  /** TTL in milliseconds (default: 7 days) */
  ttlMs?: number;
}

/**
 * Base configuration for all providers
 */
export interface EmbeddingBaseConfig {
  /** Provider identifier */
  provider: EmbeddingProvider;

  /** Embedding dimensions */
  dimensions?: number;

  /** Cache size (number of embeddings) */
  cacheSize?: number;

  /** Enable caching */
  enableCache?: boolean;

  /** Normalization type (default: 'none' - most providers pre-normalize) */
  normalization?: NormalizationType;

  /** Persistent disk cache configuration */
  persistentCache?: PersistentCacheConfig;
}

/**
 * OpenAI provider configuration
 */
export interface OpenAIEmbeddingConfig extends EmbeddingBaseConfig {
  provider: 'openai';

  /** OpenAI API key */
  apiKey: string;

  /** Model to use */
  model?: 'text-embedding-3-small' | 'text-embedding-3-large' | 'text-embedding-ada-002';

  /** Target dimensions (for text-embedding-3-* models) */
  dimensions?: number;

  /** Base URL override */
  baseURL?: string;

  /** Request timeout in ms */
  timeout?: number;

  /** Max retries */
  maxRetries?: number;
}

/**
 * Transformers.js provider configuration
 */
export interface TransformersEmbeddingConfig extends EmbeddingBaseConfig {
  provider: 'transformers';

  /** Model name from Hugging Face */
  model?: string;

  /** Quantization level */
  quantized?: boolean;

  /** Use web worker */
  useWorker?: boolean;
}

/**
 * Mock provider configuration
 */
export interface MockEmbeddingConfig extends EmbeddingBaseConfig {
  provider: 'mock';

  /** Output dimensions */
  dimensions?: number;

  /** Simulated latency in ms */
  simulatedLatency?: number;
}

/**
 * Agentic-flow provider configuration
 * Uses optimized ONNX embeddings with:
 * - Float32Array with flattened matrices
 * - 256-entry LRU cache with FNV-1a hash
 * - SIMD-friendly loop unrolling (4x)
 * - Pre-allocated buffers (no GC pressure)
 */
export interface AgenticFlowEmbeddingConfig extends EmbeddingBaseConfig {
  provider: 'agentic-flow';

  /** Model ID (default: all-MiniLM-L6-v2) */
  modelId?: string;

  /** Embedding dimensions (default: 384) */
  dimensions?: number;

  /** Internal cache size for embedder (default: 256) */
  embedderCacheSize?: number;

  /** Model directory path */
  modelDir?: string;

  /** Auto-download model if not present */
  autoDownload?: boolean;
}

/**
 * RVF provider configuration
 * Lightweight hash-based embeddings (no neural model, sub-ms latency)
 */
export interface RvfEmbeddingConfig extends EmbeddingBaseConfig {
  provider: 'rvf';

  /** Embedding dimensions (default: 384) */
  dimensions?: number;

  /** Path to binary cache file for persistent storage */
  cachePath?: string;

  /** Similarity metric preference (default: 'cosine') */
  metric?: 'cosine' | 'l2' | 'dotproduct';
}

/**
 * Union of all provider configs
 */
export type EmbeddingConfig =
  | OpenAIEmbeddingConfig
  | TransformersEmbeddingConfig
  | MockEmbeddingConfig
  | AgenticFlowEmbeddingConfig
  | RvfEmbeddingConfig;

// ============================================================================
// Result Types
// ============================================================================

/**
 * Single embedding result
 */
export interface EmbeddingResult {
  /** The embedding vector */
  embedding: Float32Array | number[];

  /** Latency in milliseconds */
  latencyMs: number;

  /** Token usage (for API providers) */
  usage?: {
    promptTokens: number;
    totalTokens: number;
  };

  /** Whether result was from cache */
  cached?: boolean;

  /** Whether result was from persistent cache */
  persistentCached?: boolean;

  /** Whether embedding was normalized */
  normalized?: boolean;
}

/**
 * Batch embedding result
 */
export interface BatchEmbeddingResult {
  /** Array of embeddings */
  embeddings: Array<Float32Array | number[]>;

  /** Total latency in milliseconds */
  totalLatencyMs: number;

  /** Average latency per embedding */
  avgLatencyMs: number;

  /** Token usage (for API providers) */
  usage?: {
    promptTokens: number;
    totalTokens: number;
  };

  /** Cache statistics */
  cacheStats?: {
    hits: number;
    misses: number;
  };
}

// ============================================================================
// Service Interface
// ============================================================================

/**
 * Embedding service interface
 */
export interface IEmbeddingService {
  /** Provider identifier */
  readonly provider: EmbeddingProvider;

  /** Get embedding for single text */
  embed(text: string): Promise<EmbeddingResult>;

  /** Get embeddings for multiple texts */
  embedBatch(texts: string[]): Promise<BatchEmbeddingResult>;

  /** Clear cache */
  clearCache(): void;

  /** Get cache statistics */
  getCacheStats(): {
    size: number;
    maxSize: number;
    hitRate: number;
  };

  /** Shutdown service */
  shutdown(): Promise<void>;
}

// ============================================================================
// Event Types
// ============================================================================

/**
 * Embedding service events
 */
export type EmbeddingEvent =
  | { type: 'embed_start'; text: string }
  | { type: 'embed_complete'; text: string; latencyMs: number }
  | { type: 'embed_error'; text: string; error: string }
  | { type: 'batch_start'; count: number }
  | { type: 'batch_complete'; count: number; latencyMs: number }
  | { type: 'cache_hit'; text: string }
  | { type: 'cache_eviction'; size: number };

/**
 * Event listener type
 */
export type EmbeddingEventListener = (event: EmbeddingEvent) => void | Promise<void>;

// ============================================================================
// Similarity Functions
// ============================================================================

/**
 * Similarity metric type
 */
export type SimilarityMetric = 'cosine' | 'euclidean' | 'dot';

/**
 * Similarity result
 */
export interface SimilarityResult {
  /** Similarity score (0-1 for cosine, unbounded for others) */
  score: number;

  /** Metric used */
  metric: SimilarityMetric;
}

